(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-kvcache-centric-mooncake"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-1\">一 · 从一次 TTFT 雪崩说起</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-2\">二 · 它到底解决什么：重复前缀的算力浪费</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-3\">三 · 它不解决什么：三条明确的失效线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-4\">四 · 机制骨架：一次请求在池里的完整路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-5\">五 · 与相邻形态的边界：为什么不是分页共享或阶段拆池</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-6\">六 · 命中率之外的账：什么时候不该把 KV 抬成一级调度对象</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-7\">七 · 请求到达：最长前缀匹配与前缀索引结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-8\">八 · 调度决策：命中收益与传输成本的比较</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-9\">九 · 执行节点：加载复用块与增量 prefill</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-10\">十 · Decode 阶段：按 KV 局部性粘滞请求</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-11\">十一 · 池容量治理：LRU 叠加热度与版本失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-12\">十二 · 端到端代价归集与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-13\">十三 · 命中率公式：把“省了多少”拆成可加权的两个和</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-14\">十四 · 时间公式：算力项与传输项的量纲对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-15\">十五 · 调度目标：命中收益减传输成本的最大化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-16\">十六 · 伪代码：从索引匹配到块注册的完整闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-17\">十七 · 淘汰与失效：LRU 加热度为何不够，版本维度必须进键</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-18\">十八 · 索引吞吐：公式里没写但决定规模上限的一项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-19\">十九 · 命中收益与搬运成本的逐项拆解：边界在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-20\">二十 · 请求形态：什么样的负载才配得上全局池</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-21\">二十一 · 长度分布与批大小：命中率如何反过来决定批</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-22\">二十二 · 并发与SLO：TTFT与集群级goodput的双目标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-23\">二十三 · 负载不对时的三种塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-24\">二十四 · 配方落地：把负载特征写进调度参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-25\">二十五 · 负载配方与失效边界：命中率之外的三个约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-26\">二十六 · 硬件档位：按互联带宽与KV容量反推节点形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-27\">二十七 · 并行拓扑：TP/EP/PP与池的耦合方式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-28\">二十八 · 量化方案：精度档位与KV池的版本一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-29\">二十九 · KV策略：池容量、淘汰与粘滞的联合参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-30\">三十 · 调度参数：批大小、队列与SLO的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-31\">三十一 · 可复现的配置思路：从负载配方倒推五元组</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-32\">三十二 · 配方失效的三个临界点与代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-33\">三十三 · 命中收益与搬运成本的临界点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-34\">三十四 · 索引查询：高并发下的隐形瓶颈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-35\">三十五 · 互联带宽：KV搬运与集合通信抢同一条路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-36\">三十六 · 显存与池容量的淘汰博弈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-37\">三十七 · 功耗与规模上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-38\">三十八 · 规模上去以后先崩的顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-39\">三十九 · 池化边界：索引吞吐、互联带宽与版本失效的三重塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-40\">四十 · 精度问题的定位：从“命中块”开始怀疑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-41\">四十一 · OOM 的三条来源与容量闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-42\">四十二 · 批抖动：命中率波动如何传导到批大小</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-43\">四十三 · 路由不均与尾延迟尖刺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-44\">四十四 · 监控面与回滚闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-45\">四十五 · 池化失效的五种形态与可回滚的诊断面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-46\">四十六 · 同族算法的分界坐标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-47\">四十七 · 决策表：按负载形态选族</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-48\">四十八 · 节点选择的收益-成本判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-49\">四十九 · 与阶段拆池的组合边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-50\">五十 · 适用条件的量化门槛</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-kvcache-centric-mooncake-sec-51\">五十一 · 选型边界：何时该用全局KV池，何时退回同族方案</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:593px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 592.6 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"510.6\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求到达后先在前缀索引中做最长前缀匹配，返回可复用的KV块列表与剩余待算t…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"510.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">调度器按KV块所在节点、传输带宽与队列负载选择prefill执行节点</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"510.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">执行节点加载复用块、仅对剩余token做prefill，新KV块注册进全局…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"510.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">decode阶段按KV局部性把请求粘滞到持有其KV的节点，减少跨节点搬运</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"510.6\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">池按LRU+热度淘汰冷块，训练侧权重切换时按版本失效相关块</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-kvcache-centric-mooncake-sec-1\">一 · 从一次 TTFT 雪崩说起</h3>\n<p>某集群做 RL 后训练的 rollout 服务，prefill 与 decode 早已拆成两个池。一个 group 里同一条 prompt 被采样多次，多轮对话的会话又反复引用同一段历史。上线初期指标正常，直到某个采样轮次并发抬升：prefill 池的排队时间从稳态水平突然拉长，TTFT 分布尾部被拽出一条长尾，而 decode 池的显存占用同时逼近上限。运维先怀疑是批调度退化，调小批、调大超时，没有效果；又怀疑是某个节点掉队，摘掉节点后长尾仍在。真正的病因在事后才被定位：每个 prefill 节点各自维护一份本地前缀缓存，请求被负载均衡器按轮询打散，同一条 prompt 的多份采样被分到不同节点，每台机器都从零算了一遍相同前缀。集群整体命中率极低，prefill 算力被重复消耗，而 decode 侧因为请求被反复迁移，KV 在节点间来回搬运，互联带宽被占满，粘滞策略失效，TTFT 抖动被进一步放大。</p>\n<p>这个事故的性质不是“某个算子慢”，而是调度对象选错了。分离式架构把 prefill 与 decode 拆开之后，KV cache 变成了跨阶段、跨节点的流动资产，但调度器眼里仍然只有“请求”和“token”，没有“可复用的 KV 块”。本地缓存各自为政，全局视角缺失，命中率就只能靠运气。KV 中心分离式池化要解决的正是这件事：把 KV cache 升为一级调度对象，建立全局可复用前缀池，让 prefill 调度先问“这块前缀谁已经有”，再决定“谁来算、搬多少”。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-2\">二 · 它到底解决什么：重复前缀的算力浪费</h3>\n<p>问题的量化形式很直接。设请求 $$i$$ 的 prompt 长度为 $$L_{\\text{prompt},i}$$，其中可与全局池中已有块匹配的最长前缀长度为 $$\\ell_{\\text{prefix},i}$$，则集群命中率为</p>\n<div class=\"formula\">$$\\text{hit} = \\frac{\\sum_i \\ell_{\\text{prefix},i}}{\\sum_i L_{\\text{prompt},i}}$$</div>\n<p>命中部分本可以跳过计算，但代价并非为零——它要么在本地命中，要么需要从持有块的节点搬运过来。于是单请求的 prefill 时间近似为</p>\n<div class=\"formula\">$$T_{\\text{prefill}} = \\frac{(L_{\\text{prompt}}-\\ell_{\\text{prefix}})\\cdot C}{\\text{FLOPS}} + \\frac{\\ell_{\\text{prefix}}\\cdot M_{\\text{kv}}}{\\text{BW}_{\\text{link}}}$$</div>\n<p>第一项是剩余 token 的计算成本，第二项是复用块的搬运成本，$$M_{\\text{kv}}$$ 为单位 token 的 KV 字节数。这个式子说明：命中不是免费的，命中收益必须与传输成本同台比较。事故里的轮询调度恰恰把第二项推到了极大——请求被分到没有块的节点，$$\\ell_{\\text{prefix}}$$ 名义上存在，实际却要跨节点搬运甚至重算，收益被抵消。池化机制把“命中在哪、搬多少、谁来算”变成一次显式决策：</p>\n<div class=\"formula\">$$\\max_{n} \\left( C_{\\text{hit}}(n) - \\frac{S_{\\text{KV}}(n)}{BW(n)} \\right)$$</div>\n<p>其中 $$C_{\\text{hit}}(n)$$ 是节点 $$n$$ 可复用前缀节省的 prefill 算力，$$S_{\\text{KV}}(n)$$ 是需搬运的 KV 字节数，$$BW(n)$$ 是该节点到块所在位置的可用带宽。调度器在候选节点间取这个差值最大者，而不是按轮询或最短队列。对 group rollout 这种同 prompt 多采样的形态，第一条采样把前缀块注册进池并标记热度，后续采样直接命中，prefill 算力节省与命中率成正比；对多轮对话，历史引用段落在池中稳定驻留，每轮只算新增 token。这是它解决的问题边界：<strong>前缀重复度高、且重复发生在跨请求跨轮次尺度上的负载</strong>。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-3\">三 · 它不解决什么：三条明确的失效线</h3>\n<p>第一条线是权重版本切换。RL 后训练高频更新权重，旧权重算出的 KV 块在新版本下语义失效，池必须按版本批量失效相关块。版本切换越频繁，缓存大面积失效越密集，命中率呈周期性塌陷，prefill 算力节省在切换窗口内归零。这不是池化机制能消除的，它只能把失效做得更精准——按版本标记、只失效相关块，而不是整池清空。判断适用性时要先问：权重更新周期与请求前缀的生命周期谁更长。若更新远快于前缀复用窗口，池化的收益会被反复清零。</p>\n<p>第二条线是索引查询吞吐。全局前缀索引要在大并发下做最长前缀匹配，返回可复用块列表与剩余待算 token。索引本身是元数据服务，高并发时查询可能成为瓶颈，命中率带来的算力收益被元数据开销抵消。规模上限因此不由 GPU 决定，而由索引查询吞吐与互联带宽共同约束。事故中后期出现的 TTFT 抖动，一部分正是块迁移占满互联带宽所致——跨节点搬运把 $$\\frac{S_{\\text{KV}}(n)}{BW(n)}$$ 这一项推到不可接受，decode 粘滞策略随之失效。</p>\n<p>第三条线是低重复负载。若请求之间前缀几乎不共享，池里全是冷块，LRU+热度淘汰不断驱逐，索引查询与块注册的开销纯属负收益。这类负载应退回按阶段拆池的简单形态，不必引入全局池。三条线合起来给出适用边界的判据：前缀重复度高、多轮对话与 group rollout 占比大、权重更新周期长于复用窗口、互联带宽足以承载块迁移——四条同时成立，池化才是正收益。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-4\">四 · 机制骨架：一次请求在池里的完整路径</h3>\n<p>按数据流顺序拆开看。请求到达后，先在全局前缀索引中做最长前缀匹配，返回两部分：可复用的 KV 块列表，以及剩余待算 token 数。这一步只读元数据，不碰 KV 本体。接着调度器拿这份列表做节点选择：候选节点按“块是否已在本地、跨节点搬运字节数、传输带宽、队列负载”排序，用上面的差值公式取优。被选中的 prefill 执行节点加载复用块，仅对剩余 token 做 prefill，算完的新块注册进全局池并标记热度。decode 阶段则按 KV 局部性把请求粘滞到持有其 KV 的节点，减少跨节点搬运；池按 LRU+热度淘汰冷块，控制池容量与索引规模。</p>\n<p>伪代码层面的决策可以写成：对每个候选节点 $$n$$，计算本地已有块集合与请求最长前缀的交集，得到 $$C_{\\text{hit}}(n)$$ 与 $$S_{\\text{KV}}(n)$$，再除以该节点到块源的带宽，取最大者；若所有候选的差值都为负，说明搬运成本高于重算成本，直接本地重算反而更优。这个“负值即重算”的分支是池化调度与朴素缓存的关键差别：缓存不是无条件命中，命中要过成本关。工程上这意味着调度器必须拿到实时带宽与队列负载，而不是静态拓扑表。</p>\n<p>代价随之而来。全局索引与块迁移带来元数据开销，高并发下索引查询可能成为瓶颈；块注册与热度更新是写路径，会与读路径争抢索引服务容量。容量规划时要把索引 QPS 当作独立资源来算，而不是当作免费的路由表。事故复盘里被忽略的一点正是：轮询调度看似“均衡”，实则把命中率压到极低，让 prefill 算力与互联带宽同时被浪费——池化把这个隐性成本显式化，代价是引入了一个必须被容量规划的元数据平面。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-5\">五 · 与相邻形态的边界：为什么不是分页共享或阶段拆池</h3>\n<p>单卡内的分页 KV 批量 Rollout 做的是块级分配与前缀共享，它的复用半径在一张卡、一个进程内，解决的是显存碎片与同批前缀重复；预填解码分离 Rollout 按阶段拆池，解决的是两阶段资源画像不同、互相干扰的问题。两者都不回答“跨节点、跨请求、跨轮次的 KV 该由谁持有、该不该搬”。KV 中心分离式池化把 KV cache 升为一级调度对象，复用半径扩到集群，并把缓存、传输、计算三者的成本放进同一个比较式里。这也是它与前两者的分工：卡内碎片与阶段隔离交给它们，全局复用与成本比较交给池化。</p>\n<p>边界判断可以用一个具体例子收束。一个多轮对话服务，会话历史长、轮次多、并发中等，前缀在会话内高度重复但跨会话重复有限：池化的收益主要来自会话内复用与 decode 粘滞，索引压力可控，是适配形态。反过来，一个短 prompt、高并发、前缀几乎不共享的在线服务，池里冷块比例高，索引 QPS 却随并发线性上涨，此时池化的元数据开销会吃掉全部收益，应退回阶段拆池加本地分页共享。事故集群的负载恰在前者与后者之间：group rollout 带来同 prompt 多采样，属于高重复；但轮询调度与频繁权重切换把两条失效线同时触发，才酿成 TTFT 雪崩。判断一个集群该不该上池化，先量三件事——前缀重复度分布、权重更新周期、互联带宽余量——再决定池的容量与失效策略，而不是先上机制再补容量。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-6\">六 · 命中率之外的账：什么时候不该把 KV 抬成一级调度对象</h3>\n<p>先看一次典型的线上塌陷。RL 后训练集群里，group rollout 对同一 prompt 采样几十条轨迹，多轮对话又反复引用同一段历史，前缀重复度极高，理论上正是全局 KV 池最舒服的负载。但训练侧按固定节奏切换权重版本，每次切换都让池中与该版本绑定的 KV 块集体失效；与此同时并发爬升，全局前缀索引的最长前缀匹配查询从“每请求一次”变成调度路径上的串行点。结果是命中率呈周期性锯齿：版本刚切完的一段时间里 <span class=\"formula\">$$\\text{hit} = \\frac{\\sum_i \\ell_{\\text{prefix},i}}{\\sum_i L_{\\text{prompt},i}}$$</span> 接近零，prefill 全额重算，TTFT 抬升；命中率回升后，索引查询与块迁移的元数据开销又把收益吃掉一部分。这不是池化本身错了，而是它的收益函数被两个外部变量——权重版本稳定性与索引吞吐——钳住了。</p>\n<p>把调度决策写成显式比较，边界就清楚了。节点 <span class=\"formula\">$$n$$</span> 被选中的条件是命中节省的算力减去搬运 KV 的时间仍为正：<span class=\"formula\">$$\\max_{n} \\left( C_{\\text{hit}}(n) - \\frac{S_{\\text{KV}}(n)}{BW(n)} \\right)$$</span>。代入 prefill 时间分解 <span class=\"formula\">$$T_{\\text{prefill}} = \\frac{(L_{\\text{prompt}}-\\ell_{\\text{prefix}})\\cdot C}{\\text{FLOPS}} + \\frac{\\ell_{\\text{prefix}}\\cdot M_{\\text{kv}}}{\\text{BW}_{\\text{link}}}$$</span> 可以看出：当 <span class=\"formula\">$$\\ell_{\\text{prefix}}$$</span> 很小（短 prompt、低重复），第一项省不下多少，第二项却实打实占用互联带宽；当 <span class=\"formula\">$$BW_{\\text{link}}$$</span> 被其他流量挤占，搬运项迅速主导，命中反而变成负收益。此时正确动作是退回本地计算，而不是硬凑全局复用。</p>\n<p>因此这套方案不解决的问题必须提前讲明。它不解决单请求内部的算力效率问题——tcgen05、TMEM、2-SM MMA 那一层的算子利用率与它无关；它不解决 decode 阶段的显存带宽瓶颈，KV 池只改变“块在哪”，不改变“每步要读多少”；它也不解决权重版本高频变动下的缓存一致性问题，只能靠按版本失效相关块做被动止损。它真正擅长的是前缀重复度高、多轮对话与 group rollout 占比大的多节点集群，且规模上限被索引查询吞吐与互联带宽两头夹住。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>池化收益</th><th>主要代价</th></tr></thead><tbody><tr><td>长前缀、高重复、版本稳定</td><td>prefill 算力按命中率线性节省</td><td>索引查询、块注册元数据</td></tr><tr><td>短 prompt、低重复</td><td>接近零</td><td>搬运带宽白白消耗</td></tr><tr><td>权重高频切换</td><td>周期性归零</td><td>大面积失效 + 重算尖峰</td></tr><tr><td>互联带宽饱和</td><td>被搬运时间抵消</td><td>decode 粘滞失效、TTFT 抖动</td></tr></tbody></table>\n<p>工程判断落在准入条件上：把“前缀重复度”和“权重版本间隔”当作池化开关的两个输入，而不是默认全量开启。版本间隔短于池内 KV 平均寿命时，池的期望命中率被结构性压低，此时应缩小池容量、只保留跨版本稳定的系统提示与工具定义块，把 LRU+热度淘汰的阈值调紧，让冷块尽快让出索引条目；互联带宽接近饱和时，应把 <span class=\"formula\">$$S_{\\text{KV}}(n)/BW(n)$$</span> 的估计值纳入调度打分并设硬上限，超过即拒绝跨节点复用、就地重算。这一步不做，池化就从“省算力”退化成“用带宽换一点算力”，在高并发下净值为负。</p>\n<h3 id=\"alg-kvcache-centric-mooncake-sec-7\">七 · 请求到达：最长前缀匹配与前缀索引结构</h3>\n<p>请求进入系统时，第一件事不是排队等 GPU，而是被送进前缀索引做一次最长前缀匹配。索引的键是 token 序列的块级哈希（通常以固定 token 数为一块，块内 token 序列决定哈希），值是持有该 KV 块的节点列表、块版本号与热度计数。匹配沿请求的 prompt token 逐块推进，直到哈希失配或遇到已被淘汰的块，返回两个输出：可复用 KV 块列表（含所在节点、块偏移、版本）与剩余待算 token 区间。这一步的输入是 prompt token 序列与当前权重版本号；输出是复用计划；代价是元数据查询——每次匹配要做若干次哈希查找与版本比对，纯 CPU/内存操作，不占 SM，但在高并发下会与调度器争抢同一批元数据服务线程。</p>\n<p>索引查询的吞吐直接决定集群能接住多少请求。设单次匹配需查 $b$ 个块、每块一次哈希查找耗时 $t_q$，则单请求索引开销约为 $b\\cdot t_q$；当并发请求数 $N$ 上升，索引服务的 QPS 需求为 $N\\cdot b/t_{\\text{req}}$，一旦超过元数据服务的能力，查询排队就会把 TTFT 抬高，而此时 GPU 可能还在空闲等活。这是本机制的第一个结构性瓶颈：命中率越高、块越碎，索引压力越大。工程上常见的做法是把索引分片、把块做大以降低查找次数、把版本比对下推到块内元数据，但这些都是用命中粒度换查询吞吐的取舍。</p>\n<p>具体例子：group rollout 中同一 prompt 被采样 $k$ 次，第 1 次请求匹配为空、全量 prefill 并把新块注册进池；第 2 到第 $k$ 次请求在索引中命中整段 prompt 前缀，返回的剩余待算 token 数为零，prefill 阶段直接跳过。命中率按前文公式 $\\text{hit}=\\sum_i \\ell_{\\text{prefix},i}/\\sum_i L_{\\text{prompt},i}$ 计，此例中命中率接近 1，节省的 prefill 算力与命中长度成正比。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-8\">八 · 调度决策：命中收益与传输成本的比较</h3>\n<p>拿到复用块列表后，调度器要决定这次 prefill 在哪个节点执行。候选节点集合由块所在节点、有空闲 prefill 容量的节点、以及互联拓扑上距离较近的节点共同构成。决策目标写成：</p>\n<div class=\"formula\">$$\\max_{n} \\left( C_{\\text{hit}}(n) - \\frac{S_{\\text{KV}}(n)}{BW(n)} \\right)$$</div>\n<p>其中 $C_{\\text{hit}}(n)$ 是节点 $n$ 上可复用前缀为本次请求节省的 prefill 算力（折算成时间），$S_{\\text{KV}}(n)$ 是需从其他节点搬运到 $n$ 的 KV 字节数，$BW(n)$ 是该路径的有效带宽。这个式子的工程含义是：命中收益不是免费的，它要么以“在块所在节点算”兑现，要么以“把块搬过来算”兑现，两者必须在同一量纲上比较。若某节点命中很长但块在远端、搬运量 $S_{\\text{KV}}$ 大，则搬运时间可能吃掉全部命中收益；反之若本地命中短但零搬运，反而更快。</p>\n<p>代入前文的 prefill 时间分解：$T_{\\text{prefill}} = (L_{\\text{prompt}}-\\ell_{\\text{prefix}})\\cdot C/\\text{FLOPS} + \\ell_{\\text{prefix}}\\cdot M_{\\text{kv}}/\\text{BW}_{\\text{link}}$，第一项是剩余 token 的计算时间，第二项是复用块的搬运时间。调度器实际是在最小化这两项之和，同时受队列负载约束——队列长的节点即使命中高，排队延迟也会抵消收益，因此决策里还要叠加各节点当前队列深度。代价体现在两个方向：决策本身要读全局状态（块位置、带宽、队列），这是一次跨节点的元数据聚合，高频调度下同样是元数据开销；决策错了则要么白搬 KV 占满互联带宽，要么放弃命中白算 prefill。</p>\n<p>具体例子：多轮对话的第 3 轮请求，历史前缀 8k token 的 KV 块分布在节点 A，节点 B 空闲且与 A 之间 NVLink 带宽高。若搬运 8k token 的 KV 字节耗时小于在 B 上重算这 8k token 的 prefill 耗时，调度器选 B 并支付搬运；否则选 A 就地算剩余 token。这个比较每请求做一次，是 KV 中心调度区别于按阶段拆池的核心动作。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-9\">九 · 执行节点：加载复用块与增量 prefill</h3>\n<p>执行节点收到任务后，输入是复用块列表与剩余 token 区间，动作分三步：先把复用块从其所在位置加载进本节点的 KV 存储（若是本地命中则只做地址映射，零拷贝），再对剩余 token 做 prefill 计算，最后把新产生的 KV 块写入本地并注册进全局池。增量 prefill 的关键是位置编码与注意力掩码必须与“前缀已存在”一致——复用块被视为已计算的上下文，新 token 的 attention 要跨过这些块，因此 kernel 的 KV 读取路径要能直接寻址池中块，而不是假设 KV 在连续显存里。这正是分页块表在跨节点场景下的延伸：块表不再只描述单卡显存，而描述“哪些块在哪个节点的哪个偏移”。</p>\n<p>这一步的代价分三块：加载复用块的搬运带宽、剩余 token 的算力、新块注册的元数据写入。搬运量与命中长度成正比，算力与未命中长度成正比，两者之和就是本步骤的墙钟时间。工程上要把“加载”和“计算”重叠起来——先加载靠前的块、同时对已就绪部分开始 attention，否则加载成为串行前缀，TTFT 被拉长。新块注册要标记热度（被命中次数、最近访问时间），这是后续淘汰决策的输入，写入本身是元数据操作，高并发下同样计入索引服务负载。</p>\n<p>具体例子：一次 4k prompt 的请求命中 3k、剩余 1k。执行节点搬运 3k token 的 KV 块（字节数由层数、头数、头维度与精度决定），同时对 1k token 做 prefill，新产生的 1k KV 块追加到池中并继承该前缀的热度。若该前缀在接下来若干请求中反复被命中，热度上升，淘汰优先级下降；若长期无人引用，热度衰减，进入 LRU 候选。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-10\">十 · Decode 阶段：按 KV 局部性粘滞请求</h3>\n<p>Prefill 完成后请求进入 decode，此时调度对象从“前缀块”变成“这个请求自己的 KV 增长”。粘滞策略的输入是请求当前 KV 所在节点与各 decode 节点的负载，输出是把该请求固定到持有其 KV 的节点上继续自回归，除非该节点过载或故障才迁移。理由很直接：decode 每步只新增一个 token 的 KV，计算量小、对带宽敏感，若每步都把历史 KV 搬到别处，搬运成本会远超计算本身。粘滞把跨节点搬运从“每步”降为“每次迁移”，代价是负载均衡变差——热点前缀的持有节点会积累大量长请求。</p>\n<p>粘滞的代价可以用迁移频率刻画：设请求在节点上 decode $s$ 步后因负载被迁走，则摊销到每步的搬运量为 $S_{\\text{KV}}/s$；$s$ 越小，粘滞越失效，TTFT 与 TPOT 抖动越明显。因此调度器要预留“粘滞配额”，即每个 decode 节点允许承载的粘滞请求上限，超过才触发迁移，迁移时优先选拓扑近、带宽高的目标节点。这与 prefill 阶段的成本比较是同一套量纲：搬运字节除以带宽，对比重算或排队的时间。</p>\n<p>具体例子：一个长多轮对话请求在节点 C 上 decode，历史 KV 已达数十 k token。若因 C 过载被迁到 D，需搬运全部历史 KV，这一步的带宽占用会挤占其他请求的 prefill 搬运，造成集群级 TTFT 抖动。工程判断是：宁可让 C 短暂排队，也不轻易迁移长 KV 请求；短请求迁移便宜，可优先作为负载均衡的调节对象。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-11\">十一 · 池容量治理：LRU 叠加热度与版本失效</h3>\n<p>全局池的容量是有限的，淘汰策略决定命中率的长期水平。输入是每个块的最近访问时间与热度计数，输出是淘汰列表。纯 LRU 在 group rollout 场景下表现不佳：同一 prompt 的多采样请求在时间上聚集，LRU 会把刚被大量命中过的块保留，但一旦采样批次结束，这些块迅速变冷却仍占容量，挤掉多轮对话的长历史块。叠加热度后，淘汰分数同时考虑访问频次与最近性，使“高频短前缀”和“低频长前缀”能在同一池中按各自收益竞争容量。</p>\n<p>更棘手的是版本失效：训练侧权重切换后，旧权重算出的 KV 与新权重不再兼容，相关块必须整体失效。失效的输入是新权重版本号，输出是受影响块的标记与回收。代价是命中率周期性塌陷——RL 高频更新场景下，每次权重切换都把池打回冷启动，prefill 算力节省归零，直到新前缀重新积累。工程上可做的缓解是把失效粒度与权重差异挂钩：差异小的更新只失效受影响的层或块，差异大的更新才全池失效；同时把权重切换安排在采样批次边界，避免在批次中途制造大面积失效。</p>\n<p>具体例子：一次 group rollout 批次产生大量同前缀块，热度很高；批次结束后权重更新，这些块全部失效，下一批请求重新全量 prefill。若更新频繁，池的有效命中率在“高—塌陷—恢复”之间周期振荡，集群 goodput 随之波动。容量规划必须把这一振荡计入，不能按稳态命中率估算 prefill 算力需求。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-12\">十二 · 端到端代价归集与工程判断</h3>\n<p>把五步的代价按请求生命周期归集：索引匹配是元数据查询，调度决策是全局状态聚合加一次成本比较，执行节点是搬运带宽加剩余算力加注册写入，decode 粘滞是迁移摊销，池治理是淘汰与失效的元数据操作。可以看到，算力只出现在第三步的“剩余 token”上，其余四步全是元数据与带宽——这正是 KV 中心调度的成本结构：省下的是 prefill 算力，付出的是索引吞吐与互联带宽。集群级收益是否为正，取决于命中率带来的算力节省能否覆盖索引与搬运开销；当命中率高但块碎、索引查询成为瓶颈时，收益被元数据开销抵消，这是本机制最典型的失败模式。</p>\n<p>工程判断落在三个可调参数上：块大小决定索引查询次数与命中粒度，块越大查询越省但命中越粗；粘滞配额决定 decode 负载均衡与迁移频率的取舍；失效粒度决定权重切换时命中率塌陷的深度。三者共同受互联带宽约束——跨节点 KV 搬运占满带宽时，prefill 的复用块加载与 decode 的迁移会互相挤占，TTFT 抖动随之放大。因此容量规划不能只看单请求的命中收益，而要把索引 QPS、搬运字节率、粘滞请求数放在同一张资源账上核算，按集群级 goodput 而非单请求 TTFT 做决策。</p>\n<p>最后一个具体机制：调度器在每次决策后把“本次命中收益、搬运字节、实际耗时”写回块的热度与成本统计，形成闭环——后续同前缀请求的调度直接复用历史成本估计，避免每次都做全量状态聚合。这把元数据开销从“每请求一次全局查询”降为“增量更新加热度缓存”，是索引吞吐瓶颈下最直接的缓解手段。</p>\n<h3 id=\"alg-kvcache-centric-mooncake-sec-13\">十三 · 命中率公式：把“省了多少”拆成可加权的两个和</h3>\n<p>本算法的收益口径只有一个：被跳过的 prefill token 占全部 prompt token 的比例。写成 <span class=\"formula\">$$\\text{hit} = \\frac{\\sum_i \\ell_{\\text{prefix},i}}{\\sum_i L_{\\text{prompt},i}}$$</span> 时，分子是每个请求实际复用到的前缀长度之和，分母是每个请求的 prompt 长度之和。这个式子看似平凡，关键在于它把“命中”定义在 token 粒度而非请求粒度：一个 8K prompt 只命中前 2K，仍然贡献 2K 的分子，而不是记作一次失败。推导的关键一步在于分子必须按“可复用块”而非“最长公共前缀字符串”计量——前缀索引返回的是 KV 块列表，块大小固定（例如按分页粒度对齐），因此 <span class=\"formula\">$$\\ell_{\\text{prefix},i} = b \\cdot \\lfloor \\ell_{\\text{LCP},i}/b \\rfloor$$</span>，其中 <span class=\"formula\">$$b$$</span> 是块 token 数，<span class=\"formula\">$$\\ell_{\\text{LCP},i}$$</span> 是字符串意义上的最长公共前缀长度。取整向下是硬约束：KV 块只能整块复用，尾部不满一块的部分必须重算，否则块内位置编码与注意力掩码无法对齐。工程含义是：块越小，命中率越高但索引条目越多；块越大，元数据越省但尾部浪费越大。对 group rollout 场景，同一 prompt 的多次采样共享完整前缀，<span class=\"formula\">$$\\ell_{\\text{LCP},i} = L_{\\text{prompt},i}$$</span>，hit 趋近 1；对多轮对话，hit 等于历史轮次占比，随对话轮数单调上升。这个比值同时是容量规划的第一输入：集群级 prefill 算力需求近似按 <span class=\"formula\">$$(1-\\text{hit})$$</span> 缩放，hit 从 0.3 抬到 0.7 意味着同样的 GPU 池能承接两倍以上的新 token 吞吐。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-14\">十四 · 时间公式：算力项与传输项的量纲对齐</h3>\n<p>第二式 <span class=\"formula\">$$T_{\\text{prefill}} = \\frac{(L_{\\text{prompt}}-\\ell_{\\text{prefix}})\\cdot C}{\\text{FLOPS}} + \\frac{\\ell_{\\text{prefix}}\\cdot M_{\\text{kv}}}{\\text{BW}_{\\text{link}}}$$</span> 把一次 prefill 的耗时拆成两项：未命中 token 的计算时间，与复用 KV 从持有节点搬到执行节点的传输时间。这里 <span class=\"formula\">$$C$$</span> 是每 token 的 prefill 计算量（与模型层数、隐藏维、注意力结构相关），<span class=\"formula\">$$M_{\\text{kv}}$$</span> 是每 token 的 KV 字节数（层数 × 2 × 头数 × 头维 × 精度字节）。推导的关键一步是承认两项不可简单相加而应取“可重叠”的下界：计算与传输在流水线中可以并行，实际耗时更接近 <span class=\"formula\">$$\\max(\\text{计算项}, \\text{传输项})$$</span> 加上启动开销，但作为调度决策的保守估计，用和式更安全，因为它不会低估最坏情况。量纲对齐带来一个直接判据：当 <span class=\"formula\">$$\\ell_{\\text{prefix}}\\cdot M_{\\text{kv}}/\\text{BW}_{\\text{link}} &gt; (L_{\\text{prompt}}-\\ell_{\\text{prefix}})\\cdot C/\\text{FLOPS}$$</span> 时，搬运比重算更贵，此时正确决策是放弃远端复用、就地重算。这个不等式解释了为什么跨节点池化不是无条件正确：在互联带宽受限的拓扑上，长前缀的跨机搬运会吃掉全部收益。以 NVLink 5 域内与跨域两种链路对比，同一段 KV 的传输时间差出一个量级，调度器必须把 <span class=\"formula\">$$\\text{BW}_{\\text{link}}$$</span> 作为节点选择的显式参数而不是常量。对 decode 阶段，同样的量纲分析适用于粘滞决策：把请求迁到持有 KV 的节点，省下的是每步解码都要重复搬运的 KV，代价是一次性迁移，因此粘滞的收益随生成长度线性放大。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-15\">十五 · 调度目标：命中收益减传输成本的最大化</h3>\n<p>节点选择写成 <span class=\"formula\">$$\\max_{n} \\left( C_{\\text{hit}}(n) - \\frac{S_{\\text{KV}}(n)}{BW(n)} \\right)$$</span>，其中 <span class=\"formula\">$$C_{\\text{hit}}(n)$$</span> 是节点 <span class=\"formula\">$$n$$</span> 上可复用前缀所节省的 prefill 算力（折算成时间或 FLOPs），<span class=\"formula\">$$S_{\\text{KV}}(n)$$</span> 是需搬运的 KV 字节数，<span class=\"formula\">$$BW(n)$$</span> 是到该节点的有效带宽。推导的关键一步是把两项统一到时间量纲：<span class=\"formula\">$$C_{\\text{hit}}(n)$$</span> 应写成“若不复用则需多花的时间”，即 <span class=\"formula\">$$\\ell_{\\text{prefix}}(n)\\cdot C/\\text{FLOPS}_n$$</span>，这样减号两侧都是秒，可以直接比较。若保留原始算力单位，则必须除以节点算力才能与传输项相减，否则高算力节点会被系统性高估。这个目标函数还有两个隐含约束需要显式化：其一，<span class=\"formula\">$$S_{\\text{KV}}(n)$$</span> 只在 KV 不在本地时非零，本地命中时该项为零，目标退化为纯算力节省；其二，队列负载不进公式而进候选集过滤——只有负载低于阈值的节点才进入 <span class=\"formula\">$$\\max$$</span>，否则会把请求塞进一个算力节省最大但排队最长的节点。工程上更实用的变体是带惩罚的版本：<span class=\"formula\">$$\\max_n \\left( C_{\\text{hit}}(n) - \\frac{S_{\\text{KV}}(n)}{BW(n)} - \\lambda\\cdot Q(n) \\right)$$</span>，<span class=\"formula\">$$Q(n)$$</span> 为预估排队时间，<span class=\"formula\">$$\\lambda$$</span> 用来在 TTFT SLO 紧张时加重队列惩罚。代价方面，这个决策每请求执行一次，若候选节点数为 <span class=\"formula\">$$N$$</span>，单次决策的元数据查询与带宽探测开销随 <span class=\"formula\">$$N$$</span> 增长，高并发下正是索引查询成为瓶颈的来源。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-16\">十六 · 伪代码：从索引匹配到块注册的完整闭环</h3>\n<p>把机制落到可实现层面，需要三段伪代码思路。第一段是前缀匹配与剩余 token 计算：</p>\n<ul>\n<li>输入请求的 token 序列 <span class=\"formula\">$$P$$</span>；在全局前缀索引中按块粒度做最长前缀匹配，返回候选块列表 <span class=\"formula\">$$\\{(\\text{block\\_id}, \\text{node}, \\text{version})\\}$$</span> 与 <span class=\"formula\">$$\\ell_{\\text{prefix}}$$</span>；</li>\n<li>过滤掉 <span class=\"formula\">$$\\text{version} \\neq \\text{current\\_weight\\_version}$$</span> 的块，剩余部分重新计算 <span class=\"formula\">$$\\ell_{\\text{prefix}}$$</span>；</li>\n<li>输出待算 token 区间 <span class=\"formula\">$$[\\ell_{\\text{prefix}}, L_{\\text{prompt}})$$</span> 与该区间对应的位置偏移，供注意力掩码构造使用。</li>\n</ul>\n<p>第二段是节点打分与派发：对每个候选节点计算 <span class=\"formula\">$$C_{\\text{hit}}(n)$$</span>（本地已有块数 × 块 token × 每 token 计算时间）、<span class=\"formula\">$$S_{\\text{KV}}(n)$$</span>（需从其他节点拉取的块字节数）、<span class=\"formula\">$$BW(n)$$</span>（链路带宽估计）与 <span class=\"formula\">$$Q(n)$$</span>，取加权最大者派发；若最优得分为负，直接退化为“就地全量 prefill”，不搬运任何 KV。第三段是执行与回写：执行节点按块加载复用 KV 到显存池，对剩余 token 做 prefill，把新生成的 KV 按块切分、写入本地池并向全局索引注册 <span class=\"formula\">$$(\\text{block\\_id}, \\text{node}, \\text{version}, \\text{热度})$$</span>；热度按最近命中次数与时间衰减更新，供淘汰使用。代价体现在三处：索引注册是写操作，块数越多写放大越明显；块加载需要显存预留，池容量直接约束可复用块上限；版本字段使每次权重切换都要扫描索引做批量失效，RL 高频更新时这段扫描本身成为周期性开销。一个具体例子：group rollout 中同一 prompt 采样 16 次，第一次请求走全量 prefill 并注册块，后 15 次请求在索引中命中全部前缀，<span class=\"formula\">$$\\ell_{\\text{prefix}} = L_{\\text{prompt}}$$</span>，待算 token 区间为空，prefill 阶段退化为纯 KV 加载，TTFT 由传输项主导而非计算项。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-17\">十七 · 淘汰与失效：LRU 加热度为何不够，版本维度必须进键</h3>\n<p>池按 LRU + 热度淘汰冷块，这条策略的正确性依赖一个前提：块的复用价值可由访问频次近似。推导的关键一步是把块的期望复用次数写成 <span class=\"formula\">$$\\mathbb{E}[\\text{reuse}] = \\text{热度}\\cdot e^{-t/\\tau}$$</span>，<span class=\"formula\">$$\\tau$$</span> 为衰减时间常数，淘汰时比较的是“保留该块的边际收益”与“占用显存的边际成本”。纯 LRU 的问题在于它只看最近一次访问，对 group rollout 这种“短时高频、之后再不出现”的模式会误判：块在爆发期被反复命中，热度极高，但爆发结束后长期占位。加入热度衰减正是为了修正这一点。更严重的是版本维度：RL 后训练中权重周期性更新，旧权重产生的 KV 在数值上不再等价于新权重的 KV，继续复用会引入语义偏差。因此索引键必须是 <span class=\"formula\">$$(\\text{prefix\\_hash}, \\text{weight\\_version})$$</span> 二元组，权重切换时按版本批量标记失效，而不是逐块删除——标记失效是 O(1) 的元数据操作，物理回收交给淘汰器异步完成。代价是切换瞬间可用块数骤降，hit 周期性塌陷，prefill 算力节省归零，集群吞吐出现锯齿。缓解手段不是提高命中率而是缩短塌陷窗口：把权重切换与池刷新做成流水线，新版本块在切换前预热注册，旧版本块延迟回收，使 hit 的下降幅度被摊平。这里的工程判断是：在权重更新频率高于池容量周转周期的场景，全局池化的收益会被反复清零，此时应按版本分池而非单一全局池，用容量换稳定性。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-18\">十八 · 索引吞吐：公式里没写但决定规模上限的一项</h3>\n<p>前述公式都把索引查询当作零成本，实际系统中它是规模上限的来源。设并发请求数为 <span class=\"formula\">$$R$$</span>，每次查询需遍历的索引条目数为 <span class=\"formula\">$$K$$</span>，则索引侧每秒操作数为 <span class=\"formula\">$$R\\cdot K$$</span>，当它逼近索引服务的处理上限时，查询延迟进入 TTFT 的关键路径。推导的关键一步是把索引查询时间写成 <span class=\"formula\">$$T_{\\text{idx}} = \\alpha + \\beta\\cdot K$$</span>，<span class=\"formula\">$$\\alpha$$</span> 为固定开销、<span class=\"formula\">$$\\beta$$</span> 为每条目比较成本，于是总 TTFT 变为 <span class=\"formula\">$$T_{\\text{idx}} + T_{\\text{prefill}}$$</span>，命中率带来的 <span class=\"formula\">$$T_{\\text{prefill}}$$</span> 下降可能被 <span class=\"formula\">$$T_{\\text{idx}}$$</span> 上升抵消——这正是失败模式“命中率收益被元数据开销抵消”的定量表达。控制 <span class=\"formula\">$$K$$</span> 的手段是索引分层：按前缀首块哈希分片，查询只落在相关分片；对高频前缀做热索引常驻，冷前缀走磁盘或远端。代价是分片带来跨分片匹配的合并开销，热索引带来一致性维护成本。工程判断落在容量规划上：当 <span class=\"formula\">$$R\\cdot K$$</span> 成为瓶颈时，提升集群规模不再提升 goodput，此时应优先扩容索引服务或降低块粒度而非加 GPU。一个具体例子：多轮对话场景中历史轮次不断累积，单请求的匹配深度随轮数增长，<span class=\"formula\">$$K$$</span> 随之上升，若不限制匹配深度上限，长对话请求会拖慢整个索引的查询尾延迟，进而拉高全局 TTFT 的 P99。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-19\">十九 · 命中收益与搬运成本的逐项拆解：边界在哪里</h3>\n<p>把调度决策写成 <span class=\"formula\">$$\\max_{n} \\left( C_{\\text{hit}}(n) - \\frac{S_{\\text{KV}}(n)}{BW(n)} \\right)$$</span> 之后，真正决定这套池化方案能否成立的，不是命中率本身，而是这两项的比值。逐项看：<span class=\"formula\">$$C_{\\text{hit}}(n)$$</span> 是节点 n 上可复用前缀所省下的 prefill 算力，量纲是 FLOPS·时间，正比于可复用 token 数 <span class=\"formula\">$$\\ell_{\\text{prefix}}$$</span> 与该节点有效算力；<span class=\"formula\">$$S_{\\text{KV}}(n)/BW(n)$$</span> 是把这些 KV 块搬到执行节点所需的时间，量纲是秒，正比于块字节数 <span class=\"formula\">$$\\ell_{\\text{prefix}}\\cdot M_{\\text{kv}}$$</span> 与链路有效带宽。关键一步在于把两者放到同一量纲上比较：只有当 <span class=\"formula\">$$\\ell_{\\text{prefix}}\\cdot C/\\text{FLOPS} &gt; \\ell_{\\text{prefix}}\\cdot M_{\\text{kv}}/\\text{BW}_{\\text{link}}$$</span>，即 <span class=\"formula\">$$C/M_{\\text{kv}} &gt; \\text{FLOPS}/\\text{BW}_{\\text{link}}$$</span> 时，跨节点搬运才划算。这个不等式是本方案的硬边界：它只与模型的每 token 计算量与每 token KV 字节数之比、以及互联带宽有关，与命中率无关。命中率再高，若该不等式不成立，搬运成本也会吃掉全部收益。</p>\n<p>由此可推出三类失效条件。其一，长上下文、小 batch 的 decode 主导负载下，<span class=\"formula\">$$M_{\\text{kv}}$$</span> 随层数与头数线性增长而单 token 计算量被摊薄，比值逼近临界点，跨节点复用退化为纯带宽消耗；此时应收缩为节点内复用，把全局池降级为局部池。其二，RL 高频权重更新使按版本失效的块大面积作废，命中率周期性塌陷，<span class=\"formula\">$$C_{\\text{hit}}$$</span> 在更新窗口内归零而索引查询与失效标记的元数据开销照付，prefill 算力节省归零。其三，高并发下全局前缀索引的最长前缀匹配本身成为串行瓶颈，查询延迟随池规模与并发度上升，命中率收益被元数据开销抵消——这正是规模上限受索引查询吞吐约束的机理。</p>\n<p>伪代码落到可实现层面，核心是把“匹配—选址—加载—注册”四步做成可中断、可降级的状态机：</p>\n<ul>\n<li>match：对请求 prompt 做最长前缀匹配，返回块列表与剩余 token 数；索引查询设超时，超时即降级为本地匹配，避免拖住 TTFT。</li>\n<li>select：对候选节点算 <span class=\"formula\">$$C_{\\text{hit}}(n) - S_{\\text{KV}}(n)/BW(n)$$</span>，剔除不等式不成立的节点；若候选集为空，直接本地全量 prefill。</li>\n<li>load：按块粒度流水加载复用块，与剩余 token 的 prefill 计算重叠，避免先搬完再算。</li>\n<li>register：新块入池并打热度标记；权重版本变更时批量置失效位，惰性回收而非同步清扫。</li>\n</ul>\n<p>系统代价必须按最坏情况估：索引查询在高并发下是共享资源，其 QPS 上限直接决定集群可服务的请求速率；块迁移占用互联带宽，与 decode 阶段的 KV 读取争抢同一链路，搬运高峰会把 TTFT 抖动放大；decode 粘滞策略一旦因节点过载或块被淘汰而失效，请求被迫重定位，TTFT 出现尖峰。工程判断是：把不等式 <span class=\"formula\">$$C/M_{\\text{kv}} &gt; \\text{FLOPS}/\\text{BW}_{\\text{link}}$$</span> 作为池化的准入条件写进调度器，而不是把命中率当作唯一目标——命中率是结果，比值才是约束。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>降级动作</th></tr></thead><tbody><tr><td>搬运不划算</td><td>候选节点收益项为负</td><td>退化为节点内复用</td></tr><tr><td>索引查询饱和</td><td>匹配延迟超时率上升</td><td>本地匹配兜底</td></tr><tr><td>权重版本切换</td><td>失效块占比骤升</td><td>惰性回收、暂停跨节点复用</td></tr></tbody></table>\n<h3 id=\"alg-kvcache-centric-mooncake-sec-20\">二十 · 请求形态：什么样的负载才配得上全局池</h3>\n<p>KV中心分离式池化的收益不是普适的，它本质上是在用「前缀索引查询 + 跨节点KV搬运」的成本，去换「重复前缀被跳过」的算力节省。因此负载配方第一件事是判断请求形态是否落在收益区间内。这套机制真正吃的是两类形态：一是group rollout，同一prompt被采样多次，前缀完全一致、只在采样分支处发散；二是多轮对话，历史轮次被反复引用，前缀随轮次单调增长。两者的共同点是前缀重复度由业务逻辑保证，而不是靠统计碰运气。若集群里主要是单轮、短prompt、彼此无共享前缀的请求，最长前缀匹配几乎每次返回空列表，调度器仍要付出索引查询与节点选择的元数据开销，命中收益趋近于零。</p>\n<p>命中率本身要按token加权而非按请求计数，因为一次命中省下的是前缀token对应的prefill算力：</p>\n<div class=\"formula\">$$\\text{hit} = \\frac{\\sum_i \\ell_{\\text{prefix},i}}{\\sum_i L_{\\text{prompt},i}}$$</div>\n<p>这个定义决定了长度分布的重要性。长prompt且前缀占比高的请求，单个请求就能贡献大量命中token；短prompt即使命中率按请求数很高，对集群prefill算力的节省也有限。工程判断上，应当先按prompt长度分桶统计命中token占比，再决定是否把某类流量接入池。举例：一个多轮客服会话，首轮prompt较短，后续每轮都把历史拼进prompt，前缀占比随轮次上升，这类流量是池化的理想输入；而一个短查询检索型流量，prompt长度有限、前缀互不相关，接入池只会增加索引压力。</p>\n<p>代价侧要盯住索引查询的吞吐。高并发下每个请求都要做一次最长前缀匹配，索引查询从「辅助路径」变成「关键路径」，其QPS上限直接约束集群可接入的请求速率。当请求形态不匹配时，系统付出的是确定的元数据开销，换来的是不确定的命中收益，这是负载不对时最典型的亏损结构。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-21\">二十一 · 长度分布与批大小：命中率如何反过来决定批</h3>\n<p>批大小在这套机制里不是独立调参项，而是命中率的函数。设一个prefill批次里有$k$个请求命中、$m$个未命中，命中请求只剩少量待算token，未命中请求要算全长prompt。若批大小按总token数固定，命中请求会拉低批内平均计算量，导致批次里出现大量「占位但不干活」的槽位，SM利用率下降；若批大小按请求数固定，命中请求多的批次计算量偏小、未命中请求多的批次计算量偏大，批间抖动加剧。正确做法是按「剩余待算token总量」组批，让命中率高的批次装更多请求、命中率低的批次装更少请求，使每批的实际计算量落在同一区间。</p>\n<p>prefill时间由剩余token与搬运量共同决定：</p>\n<div class=\"formula\">$$T_{\\text{prefill}} = \\frac{(L_{\\text{prompt}}-\\ell_{\\text{prefix}})\\cdot C}{\\text{FLOPS}} + \\frac{\\ell_{\\text{prefix}}\\cdot M_{\\text{kv}}}{\\text{BW}_{\\text{link}}}$$</div>\n<p>第二项是容易被忽略的：命中不等于免费，复用块要从持有节点搬到执行节点。当$\\ell_{\\text{prefix}}$很大而$\\text{BW}_{\\text{link}}$被其他流量挤占时，搬运项可能超过计算项，命中反而变慢。这就是长度分布的第二个约束——超长前缀的请求在互联带宽紧张时不应当被优先命中，调度器需要把搬运成本纳入节点选择，即在命中收益与传输成本间取优：</p>\n<div class=\"formula\">$$\\max_{n} \\left( C_{\\text{hit}}(n) - \\frac{S_{\\text{KV}}(n)}{BW(n)} \\right)$$</div>\n<p>具体例子：group rollout中同一prompt采样8次，若8个请求被分散到不同节点，每个节点都要么重算前缀、要么跨节点搬运同一批KV块，互联带宽被重复占用；若调度器把它们聚到持有该前缀KV的节点，搬运成本摊薄为一次，批内剩余token又高度同质，组批效率最好。因此批大小动态调整的正确信号是「本批命中token总量 / 本批搬运字节数」，而不是队列长度。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-22\">二十二 · 并发与SLO：TTFT与集群级goodput的双目标</h3>\n<p>这套机制的SLO配方以TTFT与集群级goodput为主，而不是单请求TPOT。原因在于池化改变的是prefill路径：命中请求的TTFT由「索引查询 + 块加载 + 少量token计算」构成，未命中请求的TTFT由全长prefill构成，两者在同一队列里混排会让TTFT分布出现双峰。若调度器不区分，命中请求会被未命中请求的长prefill堵在队列里，池化的低延迟优势被队列等待吃掉。</p>\n<p>并发上升时有两个临界点。第一个是索引查询饱和点：并发请求速率超过索引服务的处理能力后，每次匹配的排队延迟线性上升，TTFT整体抬升，此时增加并发不再提升goodput。第二个是互联带宽饱和点：并发越高，同时进行的KV搬运越多，搬运与计算争抢资源，decode阶段的粘滞策略开始失效——请求被粘滞到持有KV的节点，但该节点可能已因搬运流量而过载，TTFT出现抖动。工程上应把这两个临界点作为容量规划的上界，而不是把并发推到队列打满。</p>\n<p>goodput的度量要按「有效token/秒/集群」而非「请求/秒」，因为命中请求贡献的token少但占用调度资源，按请求计数会高估吞吐。一个可操作的判断：当命中率上升但goodput不升，说明元数据开销已经抵消了算力节省，此时应收缩池的接入范围，只让高前缀占比的流量进池。这与分页KV批量Rollout在单卡内的块级共享不同——后者不承担跨节点索引与搬运成本，因此对负载形态的容忍度更高；本机制把KV升为一级调度对象，收益与代价都被放大，负载配方必须更严格。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-23\">二十三 · 负载不对时的三种塌陷</h3>\n<p>第一种是索引瓶颈型塌陷：请求形态本身有前缀，但并发太高，全局前缀索引的查询成为瓶颈，命中率收益被元数据开销抵消。表现是命中率统计看起来不低，但TTFT不降反升，prefill节点利用率没有改善。根因是索引查询与KV搬运共享同一批CPU/网络资源，查询排队挤占了调度决策的时间预算。</p>\n<p>第二种是版本失效型塌陷：RL高频权重更新使缓存大面积失效，命中率周期性塌陷，prefill算力节省归零。这是负载配方里最需要提前识别的形态——如果训练侧权重切换频率高于池内KV块的平均生命周期，池化在稳态下几乎不产生收益，只留下索引与注册开销。判断方法是比较权重切换间隔与块的平均复用间隔：前者短于后者时，池的容量被大量过期块占据，LRU+热度淘汰也来不及回收。此时应缩小池的版本跨度，只保留当前版本相关的块，或按版本分区索引，避免一次切换污染全池。</p>\n<p>第三种是带宽挤占型塌陷：跨节点KV搬运占满互联带宽，decode粘滞策略失效导致TTFT抖动。触发条件是长前缀请求占比高且节点分布分散，调度器为追求命中把请求拉向远端节点，搬运流量压过decode的常规通信。表现是decode阶段TPOT抖动、粘滞命中率下降，请求在节点间被反复迁移。缓解手段是给搬运设带宽配额，并在节点选择时对$S_{\\text{KV}}(n)/BW(n)$设上限，超过上限的命中不如本地重算。</p>\n<table class=\"mini\"><thead><tr><th>塌陷形态</th><th>触发条件</th><th>可观测信号</th><th>工程处置</th></tr></thead><tbody><tr><td>索引瓶颈</td><td>并发请求速率超过索引处理能力</td><td>命中率不低但TTFT上升</td><td>收缩入池流量，索引分片</td></tr><tr><td>版本失效</td><td>权重切换间隔短于块复用间隔</td><td>命中率周期性归零</td><td>按版本分区，缩小池跨度</td></tr><tr><td>带宽挤占</td><td>长前缀多且节点分散</td><td>TPOT抖动、粘滞命中下降</td><td>搬运配额，限制远端命中</td></tr></tbody></table>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-24\">二十四 · 配方落地：把负载特征写进调度参数</h3>\n<p>落地时不要把负载配方当成静态配置，而应做成随流量特征更新的调度参数集。三个关键参数：入池准入的前缀占比阈值、组批的剩余token目标区间、节点选择的搬运成本上限。准入阈值决定哪些流量值得付索引成本，组批区间决定SM利用率，搬运上限决定TTFT稳定性。三者互相牵制——放宽准入会提高命中率但加重索引与带宽，收紧准入则池的规模效应消失。</p>\n<p>一个可执行的闭环：按prompt长度与轮次分桶统计命中token占比与搬运字节数，若某桶的$C_{\\text{hit}}(n)$长期低于$S_{\\text{KV}}(n)/BW(n)$，就把该桶移出池；若某桶命中率高但索引排队延迟上升，就对该桶做索引分片而非全局匹配。这与预填解码分离Rollout按阶段拆池的思路不同：后者按阶段划分资源，本机制按负载形态划分准入，池的边界由成本比较决定而非由阶段决定。规模上限受索引查询吞吐与互联带宽约束，因此容量规划应把这两个量作为硬约束，先算清单位请求的索引开销与平均搬运字节，再反推可接入的请求速率，而不是先定集群规模再找负载。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-25\">二十五 · 负载配方与失效边界：命中率之外的三个约束</h3>\n<p>这套池化方案的经济性完全由前缀命中率决定，而命中率不是调度器能单方面决定的，它由负载的请求形态与长度分布写死。对group rollout（同一prompt多次采样）与多轮对话（反复引用历史），前缀占比<span class=\"inline-math\">$\\ell_{\\text{prefix}}/L_{\\text{prompt}}$</span>天然接近1，命中收益最大；反之，若请求是大量互不相关的短prompt（如独立问答、单轮检索增强），前缀池里几乎全是冷块，索引查询与块注册的元数据开销照付，prefill节省却趋近于零。长度分布还决定搬运是否划算：长前缀意味着可复用KV字节数<span class=\"inline-math\">$S_{\\text{KV}}$</span>大，跨节点搬运时间<span class=\"inline-math\">$S_{\\text{KV}}/\\text{BW}_{\\text{link}}$</span>可能超过重算成本<span class=\"inline-math\">$\\ell_{\\text{prefix}}\\cdot C/\\text{FLOPS}$</span>，此时“命中”反而是负收益。调度判据应写成<span class=\"inline-math\">$\\max_n \\left( C_{\\text{hit}}(n) - S_{\\text{KV}}(n)/BW(n) \\right)$</span>，即只在命中节省的算力大于搬运代价时才跨节点复用。</p>\n<p>并发与批大小必须随命中率动态调整，而不是固定批。高并发下全局前缀索引的查询本身成为瓶颈：每个请求都要做最长前缀匹配，索引吞吐一旦饱和，命中率带来的TTFT收益被元数据延迟吃掉，表现为队列等待上升而计算单元空转。批大小的正确配方是按“命中块数×剩余token数”而非请求数来组批，让同一节点上命中同一前缀的请求共享一次块加载，否则块迁移流量会随并发线性膨胀，占满NVLink 5与后端互联带宽。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>命中率</th><th>主要代价</th><th>系统表现</th></tr></thead><tbody><tr><td>group rollout / 多轮对话</td><td>高</td><td>块注册与热度维护</td><td>prefill算力显著节省，goodput提升</td></tr><tr><td>独立短prompt高并发</td><td>低</td><td>索引查询、元数据</td><td>TTFT抖动，收益被开销抵消</td></tr><tr><td>权重高频切换的RL</td><td>周期性塌陷</td><td>版本失效、缓存重建</td><td>命中节省归零，prefill回落到全量计算</td></tr></tbody></table>\n<p>最尖锐的失效条件是RL后训练的权重版本切换：每次更新都按版本失效相关KV块，池在大面积重建期间命中率周期性塌陷，prefill算力节省归零，而索引与迁移开销仍在。此时应把池容量与淘汰策略（LRU+热度）调向“只保留跨版本稳定的系统提示与工具描述前缀”，并对版本敏感块直接放弃复用。规模上限同样由两个硬约束封顶：索引查询吞吐与互联带宽。当decode粘滞策略因带宽饱和而失效，请求被迫跨节点取KV，TTFT出现与命中率无关的抖动——这已是负载配方不匹配的信号，而非调度算法本身的问题。</p>\n<h3 id=\"alg-kvcache-centric-mooncake-sec-26\">二十六 · 硬件档位：按互联带宽与KV容量反推节点形态</h3>\n<p>部署配方的第一层不是选卡，而是选“节点内KV容量与节点间带宽之比”。KV中心池化的收益全部来自“少算”与“少搬”的差值，因此硬件档位必须让这两个量可比较。以NVL72机柜为参照：单机柜内NVLink 5把72颗GPU连成高带宽域，KV块跨GPU搬运的成本近似按链路带宽计价；跨机柜则退化为IB/RoCE，带宽下降一个档位，搬运成本随之上升。工程判断是：<strong>把前缀池的“热区”压在单机柜内，把冷区放到跨机柜可接受的位置</strong>。若把全局池无差别铺开，最长前缀匹配返回的块列表会频繁落在远端节点，调度决策里的传输项压过命中收益。</p>\n<p>具体机制上，节点形态按“prefill节点 / decode节点 / 池存储节点”三档划分。prefill节点要求高FLOPS与高带宽入向，因为它要接收复用KV块再补算剩余token；decode节点要求大显存与稳定出向带宽，因为请求按KV局部性粘滞，KV不再频繁迁移；池存储节点可以用显存+主机内存分层，承担LRU+热度淘汰后的温块。容量规划用一条不等式约束：设单节点可容纳KV块数为<em>B</em>，集群前缀池目标容量为<em>P</em>，则<em>P</em> ≤ Σ<em>B<sub>i</sub></em>，超出部分必须靠淘汰或下沉，否则索引查询返回的块列表会包含已被换出的块，触发二次计算。代价直接体现在显存上：KV块按token数×层数×头数×精度字节计，NVFP4档位下每token的KV字节数约为FP8的一半，这决定了同一显存能装多少前缀。</p>\n<p>例子：一个group rollout场景，同一prompt采样16次，prompt长8K token。若前缀池命中该prompt的公共前缀，16次采样中只有第一次需要全量prefill，其余15次只补算采样引入的差异token。此时prefill节点的FLOPS档位可以下调，而decode节点的显存档位必须上调，因为16条序列的KV要同时驻留。这就是“档位跟着负载配方走”的具体含义：命中率越高，算力档位越松、显存档位越紧。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-27\">二十七 · 并行拓扑：TP/EP/PP与池的耦合方式</h3>\n<p>并行拓扑决定KV块在物理上如何切分，进而决定“可复用块”的粒度。张量并行（TP）把每层KV按头切到多卡，一个逻辑KV块实际是跨卡的分片集合；专家并行（EP）在MoE模型下把KV与专家分布耦合，块归属随路由变化；流水并行（PP）把层切成段，前缀块跨段存放。池化要在这三种切法上定义“块ID→分片位置”的映射，否则最长前缀匹配只能返回逻辑块，调度器无法判断搬运字节数<em>S<sub>KV</sub></em>(n)。</p>\n<p>工程上优先选择<strong>TP内聚、PP分段、EP旁路</strong>的拓扑：同一前缀块的所有TP分片落在同一NVLink域内，跨节点搬运以PP段为单位整段迁移，EP只在MoE层做局部重算而不迁移KV。这样调度决策$$\\max_{n} \\left( C_{\\text{hit}}(n) - \\frac{S_{\\text{KV}}(n)}{BW(n)} \\right)$$中的<em>S<sub>KV</sub></em>(n)可按段精确估算，而不是按整块粗估。若采用跨节点TP，一个块的搬运要拆成多路小传输，元数据开销与链路争用同时上升，命中收益被抵消。</p>\n<p>伪代码思路：调度器维护<code>block_id → [segment_id, node_id, bytes]</code>的索引，最长前缀匹配返回块列表后，按段聚合字节数，再对候选节点计算命中节省与传输时间。命中节省<em>C<sub>hit</sub></em>(n)按跳过token数×每token prefill FLOPS折算，传输时间按段字节数除以实测带宽。两者相减取最大者，若所有候选节点均为负收益，则退回本地全量prefill。</p>\n<p>代价：PP分段使KV块跨段存放，decode粘滞策略要求请求的所有段在同一节点组，否则每步decode都要跨段取KV，出向带宽被打满，TTFT抖动。例子：8段PP、每段持有一部分层KV，若decode请求被粘滞到只持有前4段的节点，后4段每token都要远端拉取，decode步延迟随段数线性上升。因此拓扑设计必须让“段集合”与“粘滞单元”对齐。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-28\">二十八 · 量化方案：精度档位与KV池的版本一致性</h3>\n<p>量化档位在池化场景下不只是算力问题，更是<strong>缓存一致性</strong>问题。NVFP4与FP8的KV字节数不同，同一前缀在两种精度下是不同的块，不能互相复用。部署配方必须固定“池内KV精度”这一全局约定，否则索引会把FP8块误配给NVFP4执行节点，触发精度转换或重算。工程判断：<strong>池内统一用一种KV精度，权重精度可按层分档</strong>。prefill补算用高精度权重保证数值稳定，decode用低精度权重压带宽，但KV块本身只存一份。</p>\n<p>公式层面，KV字节数<em>M<sub>kv</sub></em> = 2 × 层数 × 头数 × 头维 × token数 × 每元素字节。NVFP4每元素半字节级，FP8每元素一字节，二者比值直接决定池容量。传输时间项<em>ℓ<sub>prefix</sub></em>·<em>M<sub>kv</sub></em>/BW<sub>link</sub>随精度档位线性变化：精度减半，搬运时间减半，命中收益的相对权重上升。这意味着低精度KV池在高带宽域内更划算，但数值稳定性需要单独验证——这部分属于NVFP4量化稳定化的主题，此处只指出它对池化配方的影响是“精度档位必须与池的淘汰策略同版本”。</p>\n<p>代价：精度切换时全池失效。RL后训练中权重高频更新，若每次更新都换KV精度，命中率周期性塌陷到零，prefill算力节省归零。例子：一个训练步内做group rollout，若权重版本从v1切到v2且KV精度随之从FP8切到NVFP4，池内所有v1块不可复用，16次采样的公共前缀要重新prefill一遍。配方上应把精度切换与权重版本解耦：精度档位按部署周期固定，权重版本只做块失效标记，不改变块格式。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-29\">二十九 · KV策略：池容量、淘汰与粘滞的联合参数</h3>\n<p>KV策略是配方里唯一同时影响命中率、显存与带宽的三个旋钮：池容量上限、淘汰规则、decode粘滞半径。池容量按“热区驻留+温区下沉”分层设定，热区容量取单节点显存可容纳块数，温区取主机内存或远端存储。淘汰用LRU+热度，热度按块被命中次数与最近命中时间加权，避免长尾多轮对话的历史块被误淘汰。粘滞半径定义为decode请求允许被调度到持有其KV的节点组的最大跳数，跳数越多，跨节点搬运越多。</p>\n<p>联合参数的约束是一条容量-带宽平衡式：设热区容量<em>H</em>，粘滞半径<em>r</em>，则跨节点KV流量近似正比于(1−命中率)×<em>r</em>×请求速率×每请求KV字节。若<em>r</em>放大而<em>H</em>不变，命中率不升反降，因为热块被挤出。工程判断：<strong>先定<em>H</em>再定<em>r</em></strong>，<em>r</em>取“刚好覆盖热区所在节点组”的最小值。例子：NVL72机柜内18个节点组，热区铺满其中4组，则<em>r</em>=1（同组内粘滞）即可，跨组搬运只发生在冷块回填时。</p>\n<p>代价：淘汰与索引更新是元数据开销的来源。每次淘汰要从前缀索引删除块条目，每次注册要插入并更新热度，高并发下索引查询与更新争用同一把锁，成为瓶颈。配方上把索引分片：按前缀哈希分到多个索引分片，查询并行化，块注册异步批量提交。失败模式是索引查询吞吐不足时，调度器等待索引返回，TTFT被元数据延迟主导，命中收益被抵消。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-30\">三十 · 调度参数：批大小、队列与SLO的联动</h3>\n<p>调度参数在池化架构下多了一层“命中率感知”。批大小不能只按队列负载动态调整，还要按当前前缀池的命中率调整：命中率高时，prefill补算量小，批可以放大以吃满decode吞吐；命中率低时，prefill算力成为瓶颈，批要缩小以避免prefill队列积压拖长TTFT。SLO以TTFT与集群级goodput为主，goodput定义为满足TTFT约束的请求吞吐，池化收益最终体现在goodput而非单请求延迟。</p>\n<p>伪代码思路：每个调度周期采样命中率<em>h</em>与队列长度<em>Q</em>，批大小<em>B</em>按<em>B</em> ∝ <em>Q</em>/(1−<em>h</em>)的单调关系调整，上限由decode节点显存与KV块驻留量约束。当<em>h</em>下降，分母变大，<em>B</em>收缩，prefill节点获得更多算力份额；当<em>h</em>上升，<em>B</em>放大，decode吞吐提升。这条规则把命中率变成调度器的显式输入，而不是事后统计。</p>\n<p>代价：批大小频繁调整会引起KV块驻留量波动，触发淘汰与回填，跨节点带宽出现尖峰。例子：group rollout的16次采样在同一prompt上命中率接近1，<em>B</em>被放大到显存上限；下一批请求前缀各异，<em>h</em>骤降，<em>B</em>收缩，先前放大的KV块被淘汰，回填时搬运占满互联带宽，decode粘滞策略失效，TTFT抖动。配方上给批大小加变化率上限，并给淘汰加冷却窗口，避免命中率抖动直接传导到带宽。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-31\">三十一 · 可复现的配置思路：从负载配方倒推五元组</h3>\n<p>把上述四层收束成一个可复现的配置流程，输出是“硬件档位、并行拓扑、量化档位、KV策略、调度参数”五元组。流程按负载配方倒推：先测前缀重复度（group rollout同prompt多采样占比、多轮对话历史引用长度），得到预期命中率<em>h</em>；再由<em>h</em>决定prefill算力档位与decode显存档位；再由互联带宽决定热区半径与并行拓扑；最后定KV精度与调度参数。</p>\n<p>具体步骤：第一步，采集请求形态，统计公共前缀长度分布，用$$\\text{hit} = \\frac{\\sum_i \\ell_{\\text{prefix},i}}{\\sum_i L_{\\text{prompt},i}}$$估算池化上限。第二步，按<em>h</em>分配节点角色，prefill节点数与decode节点数之比取(1−<em>h</em>):<em>h</em>的近似，命中率越高，prefill节点越少。第三步，拓扑选TP内聚、PP分段，段数与粘滞单元对齐。第四步，KV精度固定为部署周期内的单一档位，权重版本只做失效标记。第五步，调度参数以命中率为显式输入，批大小变化率设上限，淘汰加冷却窗口。</p>\n<p>代价与验证：这套配方要在权重切换周期内验证命中率塌陷的恢复时间。RL高频更新场景下，每次权重切换后池内相关块失效，命中率从高位跌落再爬升，恢复时间由新请求的公共前缀重新注册速度决定。例子：若一个训练步内权重切换一次，group rollout的16次采样跨越切换点，则后半段采样的公共前缀无法复用前半段的KV，prefill算力节省减半。配方上把权重切换与rollout批次对齐，让同一批采样落在同一权重版本内，是保住命中率的关键工程判断。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-32\">三十二 · 配方失效的三个临界点与代价核算</h3>\n<p>这套配方的边界不在硬件档位本身，而在三个量的比值上：索引查询吞吐与请求到达率、互联带宽与KV搬运量、权重版本周期与缓存寿命。把最长前缀匹配放在请求入口，意味着每来一个请求都要在全局索引里做一次查询；当并发请求率逼近索引服务的QPS上限时，查询延迟会直接叠加到TTFT上，命中收益被元数据开销吃掉——这正是失败模式的第一条。工程上可核算的判据是：设单次索引查询代价为<span class=\"inline-math\">t_idx</span>、平均可复用块数为<span class=\"inline-math\">b</span>，则只有当<span class=\"inline-math\">b·t_save &gt; t_idx + S_KV/BW</span>时命中才划算，其中<span class=\"inline-math\">t_save</span>是单块省下的prefill时间。低于这个阈值就该退化为节点本地前缀共享，而不是硬撑全局池。</p>\n<p>第二个临界点是带宽。调度决策<span class=\"inline-math\">$$\\max_{n} \\left( C_{\\text{hit}}(n) - \\frac{S_{\\text{KV}}(n)}{BW(n)} \\right)$$</span>在互联空闲时几乎总选命中率最高的节点，但group rollout同prompt多采样的突发流量会把跨节点KV搬运推到带宽饱和，此时<span class=\"inline-math\">S_KV/BW</span>项迅速抬升，decode粘滞策略失效，TTFT出现抖动。配方里必须给搬运设一个硬上限：单请求搬运字节数超过阈值即放弃跨节点复用、改走本地重算，用<span class=\"inline-math\">T_prefill</span>公式里的<span class=\"inline-math\">ℓ_prefix·M_kv/BW_link</span>项与<span class=\"inline-math\">(L_prompt−ℓ_prefix)·C/FLOPS</span>项做直接比较。</p>\n<p>第三个临界点是RL高频权重更新。版本切换按版本失效相关块，等于把池子周期性清空，命中率塌陷到接近零，prefill算力节省归零。可复现的配置思路是：把权重版本号写进KV块的元数据，淘汰策略从纯LRU改为“版本内LRU+热度”，并为版本切换预留一段预热窗口——新版本上线后先只允许本地复用，等热度重新积累再开放全局池。表里给出三档规模的取舍：</p>\n<table class=\"mini\"><thead><tr><th>规模档</th><th>索引部署</th><th>KV策略</th><th>主要代价</th></tr></thead><tbody><tr><td>单机多卡</td><td>进程内前缀树</td><td>块级共享，不跨节点</td><td>池容量受HBM限制</td></tr><tr><td>多节点中等</td><td>集中索引+副本</td><td>全局池+节点粘滞</td><td>索引QPS与元数据开销</td></tr><tr><td>大规模集群</td><td>分片索引</td><td>按互联拓扑分区池化</td><td>跨区搬运占满带宽</td></tr></tbody></table>\n<p>量化档位未给出时不要臆造，配方应把量化当作正交维度：它改变<span class=\"inline-math\">M_kv</span>从而线性改变搬运成本，但不改变命中判据的结构。真正决定这套方案能否落地的是索引分片粒度与池分区是否跟NVLink域对齐——跨域搬运的带宽落差会让成本比较项失真，此时应把池边界画在域边界上，宁可牺牲一部分跨域命中率。</p>\n<h3 id=\"alg-kvcache-centric-mooncake-sec-33\">三十三 · 命中收益与搬运成本的临界点</h3>\n<p>把KV池化放到集群尺度，第一个先崩的往往不是算力，而是“搬”这件事。调度器在每个请求上做的判断，本质是在节点 n 上比较复用前缀省下的prefill算力与把KV块拉过来的时间：</p>\n<div class=\"formula\">$$\\max_{n} \\left( C_{\\text{hit}}(n) - \\frac{S_{\\text{KV}}(n)}{BW(n)} \\right)$$</div>\n<p>这个式子的量纲并不统一——前项是FLOPs，后项是秒——所以工程实现里通常把它化成同一单位的时间预算：把 C_hit 除以节点有效算力得到“省下的prefill时间”，再与 S_KV/BW 的传输时间相减。关键在于两项的缩放行为不同。C_hit 随命中长度线性增长，但 S_KV 也随命中长度线性增长，于是命中越长，搬运量越大，收益被自己的成本项吃掉一部分。真正决定胜负的是命中长度与互联带宽的比值：当 ℓ_prefix 增加时，省下的计算时间按 (ℓ_prefix·C)/FLOPS 增长，而传输时间按 (ℓ_prefix·M_kv)/BW_link 增长，两者之比等于 (C/FLOPS)/(M_kv/BW_link)。Blackwell 单节点内 HBM 带宽与 NVLink 5 的跨节点带宽相差一个量级，这个比值就决定了“多长的前缀值得跨节点搬”。短前缀跨节点搬是纯亏；长前缀跨节点搬才有意义。工程判断因此很直接：给池化调度设一个最小可搬长度阈值，低于阈值的命中只在本节点内消化，不发起跨节点拉取。</p>\n<p>具体例子：group rollout 里同一 prompt 被采样多次，第一次采样把 KV 块写进池，后续采样命中。若这些采样被调度到同一节点，命中几乎零成本；若被负载均衡打散到八个节点，每次命中都要走一趟跨节点传输，TTFT 的抖动立刻显现。这就是为什么池化必须与“粘滞”配套，而不能只做全局索引。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-34\">三十四 · 索引查询：高并发下的隐形瓶颈</h3>\n<p>全局前缀索引是这套机制的中枢，也是最先出现尾延迟的地方。最长前缀匹配在语义上是 trie 或块哈希链上的查找，单次查询的代价不高，但请求到达速率乘以并发度之后，索引就成了一个集中式服务：每个请求在进入prefill队列之前都要打一次索引，索引的 P99 直接叠加到 TTFT 上。更麻烦的是索引不是只读的——执行节点每算完一段就注册新块、标记热度，淘汰时又要删块，读写混合让索引的锁竞争与缓存一致性开销放大。</p>\n<p>代价可以用一个简单的排队视角看：设索引查询服务时间为 t_q，到达率为 λ，则索引侧的利用率 ρ = λ·t_q，当 ρ 逼近 1 时排队延迟按 1/(1−ρ) 发散。这意味着索引吞吐是集群规模的一个硬上限：请求速率上去以后，即使 GPU 侧还有余量，TTFT 也会因为索引排队而抬升。缓解手段不是加机器，而是减少查询次数与查询粒度——按块粒度而非 token 粒度索引、把热块索引下沉到节点本地做一级过滤、只对跨节点候选做全局查询。这与分页KV批量Rollout在单卡内做块级分配的思路是同一方向，只是把块表从卡内搬到了集群。</p>\n<p>失败模式的定性描述很明确：命中率收益被元数据开销抵消。当索引查询本身成为 TTFT 的主要构成时，池化带来的prefill节省在端到端指标上不再可见，goodput 不再随命中率上升。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-35\">三十五 · 互联带宽：KV搬运与集合通信抢同一条路</h3>\n<p>分离式部署下，prefill 节点与 decode 节点之间本来就有 KV 传输，池化又增加了一条“从池里拉复用块”的流量，两条流量共享 NVLink 5 与跨节点 fabric。在 NVL72 这种机架级域内，带宽相对充裕，但一旦请求被调度到跨机架节点，KV 搬运就要经过更窄的链路，此时搬运时间在 TTFT 中的占比迅速上升。</p>\n<p>这里有一个容易被忽略的耦合：decode 阶段的粘滞策略要求请求留在持有其 KV 的节点上，粘滞越强，负载越不均衡；负载均衡一旦强行打散，跨节点搬运量就上升。两者是同一枚硬币的两面。规模上去以后先崩的正是这个平衡点——粘滞带来的局部性收益被少数热点节点的队列延迟吃掉，而打散带来的搬运成本又占满互联带宽。工程上的做法是给粘滞设一个“负载上限”，超过上限才迁移，并把迁移安排在 decode 步之间的空隙，避免与正在进行的集合通信争带宽。</p>\n<p>量化这个代价只需要一个比值：单请求 KV 搬运字节数除以可用带宽，得到单次命中的传输时间下限；再乘以并发命中数，就是这一波请求对 fabric 的总占用。当这个总占用接近 fabric 容量时，任何一次权重切换引发的缓存失效都会造成搬运洪峰——因为失效后所有请求同时变成未命中，prefill 算力需求与 KV 写入量同时抬升。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-36\">三十六 · 显存与池容量的淘汰博弈</h3>\n<p>池化把 KV 从“请求私有”变成“集群共享”，显存账本随之改变。池的总容量由所有参与节点的空闲 HBM 之和决定，但可用容量不是静态的：decode 侧的在途请求会持续占用 KV，prefill 侧新算出的块又要注册进池，两边争同一片显存。LRU+热度淘汰是在这个约束下做的取舍——淘汰冷块腾出空间给热块，代价是被淘汰的块下次命中时要重算。</p>\n<p>淘汰策略的代价可以用命中率对容量的敏感度来刻画：池容量越接近工作集大小，淘汰越频繁，重算量越大；容量远大于工作集时，淘汰几乎不发生，但显存被长期占用，挤压了批大小与并发度。RL 后训练场景的工作集有一个特殊性质——权重版本切换会让一大批块同时失效，工作集在版本边界上突然缩小又迅速重新膨胀，LRU 的稳态假设被打破。这时按版本失效相关块比按 LRU 被动淘汰更划算：主动失效可以在权重切换的窗口内集中释放显存，避免“旧块占着位置但永远不再命中”的僵局。</p>\n<p>具体例子：多轮对话里历史引用很长，前缀块被反复命中，热度很高，LRU 几乎不会淘汰它；但一旦对话结束，这个块的热度骤降，却仍占着显存直到被挤出。热度衰减窗口设得太长，池的有效容量就被僵尸块侵蚀；设得太短，长对话的复用又被误杀。这个参数没有通用解，只能按负载的对话轮次分布来定。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-37\">三十七 · 功耗与规模上限</h3>\n<p>池化的功耗账本有两项容易被低估。第一项是搬运功耗：跨节点 KV 传输要走 SerDes 与 fabric 交换，单位字节的能耗远高于片内 HBM 访问，命中越长、搬运越多，这部分功耗越显著。第二项是重算功耗：未命中的 token 要重新跑 prefill，prefill 是算力密集的，功耗密度高于 decode。池化的本意是用搬运换重算，但搬运功耗与重算功耗的比值决定了这笔交易在功耗维度上是否划算——在带宽充裕的域内，搬运便宜；跨域搬运时，省下的算力可能被传输能耗抵消。</p>\n<p>规模上限因此是双约束的：索引查询吞吐给出一个软上限，互联带宽给出一个硬上限。前者可以通过减少查询粒度缓解，后者只能靠提高局部性来绕开——也就是让更多命中发生在节点内而非跨节点。这解释了为什么池化部署配方强调“按节点局部性粘滞”：不是为了省几次传输，而是为了让规模上限尽量落在带宽约束的高位。</p>\n<p>尾延迟的形态也由此确定：稳态下 TTFT 由命中路径决定，抖动来自三处——索引排队的尾部、跨节点搬运与集合通信的争抢、权重切换引发的失效洪峰。三者叠加时，P99 TTFT 可以远高于均值，而 goodput 的下降往往先于均值指标显现。容量规划时应把这三项分别建模，而不是用一个平均命中率去推集群规模。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-38\">三十八 · 规模上去以后先崩的顺序</h3>\n<p>把上述代价按规模排序，崩溃顺序大体是：先索引，再带宽，最后显存。请求速率刚上去时，GPU 还有余量，索引的 ρ 先逼近 1，TTFT 尾部抬升；继续加压，跨节点命中比例上升，fabric 占用接近饱和，搬运时间进入 TTFT 主项；再往上，池容量相对工作集不足，淘汰与重算同步增加，prefill 队列被重算请求填满，形成正反馈。显存之所以最后崩，是因为它可以靠淘汰策略腾挪，而索引与带宽没有腾挪空间。</p>\n<p>对应的工程判断是：池化的容量规划不应以“池能装多少 KV”为起点，而应以“索引能承受多少请求速率”和“fabric 能承受多少跨节点命中”为起点，反推可支持的并发与命中长度分布。当负载的跨节点命中比例超过某个由带宽决定的门槛时，扩大池反而有害——它把更多请求吸引到跨节点路径上。此时正确的动作是收缩池的全局可见范围，退化为按机架或按节点的局部池，把命中留在带宽充裕的域内。这与预填解码分离Rollout按阶段拆池的做法方向一致，区别只在于拆池的维度是拓扑而非阶段。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-39\">三十九 · 池化边界：索引吞吐、互联带宽与版本失效的三重塌陷</h3>\n<p>规模上去以后，最先崩的通常不是显存而是<strong>全局前缀索引</strong>。每个请求到达都要做一次最长前缀匹配，查询代价随池内块数与并发深度同时增长；当索引服务本身成为串行点，命中收益会被元数据开销吃掉。把调度决策写成命中收益与搬运成本的差：</p>\n<div class=\"formula\">$$\\max_{n} \\left( C_{\\text{hit}}(n) - \\frac{S_{\\text{KV}}(n)}{BW(n)} \\right)$$</div>\n<p>其中 $$C_{\\text{hit}}(n)$$ 是节点 $$n$$ 复用前缀省下的 prefill 算力，$$S_{\\text{KV}}(n)$$ 是需搬运的 KV 字节。注意这个式子只在索引能在 TTFT 预算内返回块列表时才有意义——索引延迟一旦接近 prefill 节省的时间，整条路径就退化为“先查再算”的纯开销。工程上要把索引查询与块元数据做成可水平分片的只读结构，并按前缀长度分层，长前缀优先走本地命中，短前缀直接放弃跨节点搬运。</p>\n<p>第二个塌陷点是互联带宽。跨节点搬运 KV 的成本与 $$S_{\\text{KV}}$$ 成正比，而 decode 粘滞策略的前提是“持有 KV 的节点还有余量”。当 group rollout 的同 prompt 多采样把同一前缀的并发副本推到多个节点，搬运请求会在 NVLink/NCCL 域内叠加，decode 粘滞失效，TTFT 出现抖动。可用小表判断何时该放弃搬运：</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>调度取向</th><th>系统代价</th></tr></thead><tbody><tr><td>前缀长、节点余量足</td><td>搬运复用块</td><td>省 prefill 算力，占互联带宽</td></tr><tr><td>前缀短、队列浅</td><td>本地重算</td><td>多耗算力，省一次搬运</td></tr><tr><td>索引查询超预算</td><td>降级为本地匹配</td><td>命中率下降，TTFT 可控</td></tr></tbody></table>\n<p>第三个、也是最难绕开的，是<strong>权重版本切换</strong>。RL 后训练高频更新使按版本失效的块大面积作废，命中率周期性塌陷，prefill 算力节省归零；此时池容量被冷块与半失效块占据，LRU+热度淘汰只能延缓而不能阻止。判断规模上限的准则很直接：当索引查询吞吐与互联带宽两者中任一先饱和，池化的边际收益转负，应退回按阶段拆池的预填解码分离形态，把复用限制在单节点或单机架内。功耗层面同样如此——跨节点搬运拉高互联与内存控制器活动，单位 goodput 的能耗随搬运比例上升，池的规模应止步于搬运成本仍低于重算成本的那个节点数。</p>\n<h3 id=\"alg-kvcache-centric-mooncake-sec-40\">四十 · 精度问题的定位：从“命中块”开始怀疑</h3>\n<p>KV池化路径上的精度异常，几乎从不以“数值溢出”这种直白形式出现，而是表现为同一 prompt 在不同副本上给出不一致的 logits 分布，或者长上下文里中段 token 的注意力权重突然偏移。根因往往不在算子本身，而在复用块的“血缘”：一个 KV 块被多个请求共享后，它的量化尺度、位置编码偏移、以及写入时的 dtype 必须与当前请求完全一致。工程上第一件事是给每个 KV 块打上三元标签——权重版本号、量化档位、位置基准——命中时做严格比对，不匹配就降级为未命中重新计算，而不是强行拼接。</p>\n<p>诊断手段是把命中路径做成可开关的旁路：对同一请求分别走“全量 prefill”和“池化命中”两条路，比较两者在固定几个 token 位置上的 hidden state 余弦相似度。若相似度在浅层就掉到阈值以下，说明块内数值已被污染；若只在深层偏离，通常是位置编码基准错位。代价上，这条旁路会让该请求的 TTFT 翻倍，因此只在灰度流量或采样比例上开启，不能全量常驻。</p>\n<p>一个具体例子：多轮对话中第三轮引用了第一轮的历史，池里第一轮 KV 块是在旧权重版本下写入的。若版本失效标记漏打，第三轮直接复用，模型会把旧分布当作当前上下文，输出风格漂移但语法通顺——这类错误不会触发任何数值异常告警，只能靠“同 prompt 双路对比”的离线回归发现。回滚动作很直接：把该版本号对应的块批量标记为失效，命中率瞬时下降，但精度恢复。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-41\">四十一 · OOM 的三条来源与容量闸门</h3>\n<p>池化架构的 OOM 不是单卡显存不够，而是三类资源同时被挤压：全局前缀索引的元数据、跨节点 KV 块的副本、以及 decode 节点上因粘滞策略堆积的驻留块。索引本身若用哈希表存块描述符，高并发下每个请求的最长前缀匹配要遍历候选链，元数据常驻内存随块数线性增长；块副本则是调度器为了减少搬运而做的“预取”，在带宽紧张时反而制造冗余；粘滞块则是 decode 侧为了局部性不愿释放的冷块。</p>\n<p>容量闸门应写成显式的准入公式，而不是靠 LRU 自然淘汰：</p>\n<div class=\"formula\">$$\\text{admit} = \\left[ \\frac{S_{\\text{pool}} + S_{\\text{new}}}{S_{\\text{cap}}} &lt; \\alpha \\right] \\wedge \\left[ \\frac{S_{\\text{KV}}(n)}{BW(n)} &lt; \\tau \\right]$$</div>\n<p>前一项约束池总量不超过容量上限的比例 α，后一项约束本次搬运成本不超过时间阈值 τ。两个条件任一不满足就拒绝复用、退回本地计算。这样 OOM 从“运行时报错”变成“准入时拒绝”，代价是命中率下降几个百分点，收益是 decode 节点不会在高峰被粘滞块撑爆。</p>\n<p>具体场景：group rollout 同一 prompt 采样数十条，每条都试图把前缀块拉到自己的 decode 节点，粘滞策略让这些副本谁也不释放。若没有准入闸门，单节点驻留块数随采样数线性上升，显存先于带宽耗尽。加上闸门后，超出 α 的请求退回“按需搬运、用完即弃”，显存曲线被压平，代价是这部分请求的 TTFT 多一次跨节点读取。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-42\">四十二 · 批抖动：命中率波动如何传导到批大小</h3>\n<p>批抖动指同一调度周期内，批的实际组成在“高命中”和“零命中”之间反复横跳，导致 prefill 阶段的计算量方差极大。池化把请求分成两类：命中块多的请求剩余 token 少、算得快；未命中的请求要全量 prefill、算得慢。若调度器按固定批大小打包，一个零命中请求混进高命中批，整批的完成时间被它拖长，后续 decode 的发射节奏被打乱。</p>\n<p>机制上应把批的打包单位从“请求数”改为“剩余待算 token 数”，并按命中率分桶：高命中桶走小批快周转，零命中桶走大批摊薄固定开销。伪代码思路是，先按 <code>L_prompt − ℓ_prefix</code> 排序，再在桶内做贪心装箱，桶间按队列负载动态分配 SM。代价是分桶带来额外的调度决策开销，桶数越多、元数据越碎，索引查询压力越大——这正是高并发下索引成为瓶颈的传导路径。</p>\n<p>抖动的监控指标不是平均批大小，而是批内剩余 token 数的变异系数。变异系数持续偏高说明分桶失效或命中率估计不准，应回退到“按请求数打包 + 保守批大小”的旧策略。一个例子：权重切换后的头几十秒，池内块大面积失效，命中率从常态塌陷到接近零，此时若仍按旧批大小打包，prefill 队列瞬间积压，TTFT 尖刺出现。回滚动作是把批大小临时下调并放宽 SLO 的 TTFT 目标，等新版本块重新注册、命中率爬回后再恢复。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-43\">四十三 · 路由不均与尾延迟尖刺</h3>\n<p>路由不均的根源是调度目标函数只看单节点收益，不看集群全局：</p>\n<div class=\"formula\">$$\\max_{n} \\left( C_{\\text{hit}}(n) - \\frac{S_{\\text{KV}}(n)}{BW(n)} \\right)$$</div>\n<p>当多个请求同时命中同一热点块所在的节点，该节点的队列负载被推高，而其他持有相同块的节点空闲。单请求看是“最优选择”，集群看是把热点节点打成瓶颈。尾延迟尖刺由此产生：p99 的 TTFT 由排队时间主导，而非计算时间。</p>\n<p>诊断要区分“计算尖刺”和“排队尖刺”：前者看单请求 prefill 耗时分布，后者看节点队列深度与到达率的比值。若队列深度在尖刺前持续爬升而单请求耗时平稳，就是路由不均。修法是给目标函数加负载惩罚项，把节点当前队列长度折算成等效传输成本，让调度器在“近但忙”和“远但闲”之间做真实比较。代价是部分请求多付一次跨节点搬运，互联带宽占用上升，命中收益被摊薄。</p>\n<p>具体例子：多轮对话的公共系统提示被大量请求共享，形成超级热点块。所有请求都倾向路由到持有该块的那个 prefill 节点，该节点队列爆满，而其他节点上的同块副本无人问津。加负载惩罚后，请求被摊到多个副本节点，单请求搬运成本略增，但 p99 TTFT 被削平。监控上应对每个热点块维护“副本利用率”指标，长期偏斜说明副本放置策略需要重平衡。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-44\">四十四 · 监控面与回滚闸门</h3>\n<p>监控要覆盖四个面，缺一不可：命中面（全局命中率、分桶命中率、块热度分布）、索引面（查询延迟 p50/p99、索引条目数、匹配链长度）、传输面（跨节点 KV 字节速率、互联带宽饱和度）、调度面（批内 token 变异系数、节点队列深度、粘滞块驻留量）。四个面里任何一个的 p99 越界，都应触发降级而非告警了事。</p>\n<p>回滚闸门按代价从低到高排成三级。一级：关闭粘滞策略，decode 改为按需读取，牺牲局部性换显存与带宽余量；二级：把命中阈值调高，只复用高热度块，冷块一律重算，命中率下降但索引查询压力同步下降；三级：整体退回“无全局池”的分离式预填/解码，KV 不再跨节点复用，回到单节点分页分配。三级回滚的代价是 prefill 算力节省归零，但系统回到已知稳定的基线。</p>\n<p>闸门触发条件应绑定具体指标而非主观判断：索引查询 p99 超过 prefill 单步耗时的一定比例，说明元数据开销已抵消命中收益，直接跳二级；权重版本切换后命中率跌破基线的一半，跳一级并临时下调批大小；跨节点带宽饱和度持续打满且 TTFT 尖刺频发，跳三级。每次回滚都记录触发指标与回滚前后的命中率、TTFT、goodput 三元组，作为下次灰度放量的判据。</p>\n<p>工程判断落在最后一道闸门上：池化架构的收益完全建立在“命中率 × 单次命中节省”大于“索引与搬运开销”之上，而这个不等式在权重高频更新、热点块集中、互联带宽紧张三种条件下会翻转。翻转发生时，最快的止损不是调参，而是把 KV 从一级调度对象降回普通缓存，让调度器重新以请求为单位做决策——这正是回滚三级存在的意义。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-45\">四十五 · 池化失效的五种形态与可回滚的诊断面</h3>\n<p>全局前缀池把KV升为一级调度对象后，故障不再表现为单卡OOM或单请求超时，而是沿“索引—搬运—粘滞”三条链路扩散。第一类是<b>精度漂移</b>：复用块来自不同权重版本或不同量化档位时，前缀KV与当前decode侧的计算图语义不一致，表现为长上下文末段logits偏移、重复引用历史时答案前后矛盾。这类问题不会触发任何资源告警，只能靠<b>影子校验</b>发现——按固定比例抽样请求，对命中块重新prefill少量token并与复用路径比对hidden state的余弦距离，超阈值即把该版本块整体标记失效。第二类是<b>OOM</b>，但它通常不是池满，而是粘滞策略把decode请求钉在持有KV的节点上，导致该节点decode batch与KV块同时膨胀；诊断要看“每节点KV字节/显存”与“粘滞请求数”的联合曲线，而非单看池占用率。</p>\n<p>第三类是<b>批抖动</b>与<b>路由不均</b>。命中率随请求形态波动，批大小按命中率动态调整时，prefill队列的有效token数会在“几乎全命中”和“几乎全未命中”之间跳变，形成周期性空批与拥塞交替。调度目标本身给出了抖动来源：</p>\n<div class=\"formula\">$$\\max_{n} \\left( C_{\\text{hit}}(n) - \\frac{S_{\\text{KV}}(n)}{BW(n)} \\right)$$</div>\n<p>当$$BW(n)$$被其他租户的搬运占满，最优节点会瞬间从“高命中远节点”切到“低命中近节点”，路由随之震荡。工程上应给该目标加滞回：节点得分需连续若干调度周期领先才切换，并把$$S_{\\text{KV}}(n)/BW(n)$$的带宽估计做成滑动窗口而非瞬时值。路由不均的另一半来自索引分片——前缀索引若按hash分片，热点前缀会集中到少数分片，表现为部分prefill节点长期空闲而少数节点队列堆积。</p>\n<p>第四类是<b>尾延迟尖刺</b>，也是池化最典型的SLO杀手。TTFT由未命中token的计算与命中块的搬运串联构成：</p>\n<div class=\"formula\">$$T_{\\text{prefill}} = \\frac{(L_{\\text{prompt}}-\\ell_{\\text{prefix}})\\cdot C}{\\text{FLOPS}} + \\frac{\\ell_{\\text{prefix}}\\cdot M_{\\text{kv}}}{\\text{BW}_{\\text{link}}}$$</div>\n<p>命中率越高，第二项占比越大，一旦互联带宽被并发搬运挤占，TTFT的P99会脱离均值数个量级，而均值几乎不动——这正是“命中率提升但SLO变差”的典型现场。诊断应把TTFT拆成计算段与搬运段分别打点，并对搬运段设带宽配额与优先级，避免decode粘滞流量与prefill搬运争抢同一条链路。第五类是<b>RL高频权重更新导致的命中率周期性塌陷</b>：每次版本切换按版本失效相关块，池在短时间内近乎清空，prefill算力节省归零，同时失效块释放与重新注册造成索引写放大。可回滚的做法是保留上一版本块的只读副本并设短TTL，新版本请求优先走新块、旧块仅服务尚未完成的在途请求，把“全量失效”降级为“渐进替换”。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要观测</th><th>回滚动作</th></tr></thead><tbody><tr><td>精度漂移</td><td>影子校验余弦距离</td><td>按版本失效块，关闭跨版本复用</td></tr><tr><td>OOM</td><td>节点KV字节/粘滞请求数</td><td>解除粘滞，回退到按队列负载路由</td></tr><tr><td>批抖动</td><td>有效token数与空批率</td><td>固定批大小，关闭动态调整</td></tr><tr><td>路由不均</td><td>分片查询QPS与节点队列方差</td><td>索引改前缀树分片，加得分滞回</td></tr><tr><td>尾延迟尖刺</td><td>TTFT搬运段P99</td><td>搬运限流，命中块降级为本地重算</td></tr></tbody></table>\n<p>监控面的最小集合是：索引查询P99与分片QPS（判断元数据是否已成瓶颈）、命中率与命中块平均长度、搬运字节与链路利用率、粘滞命中比、版本失效块比例。回滚必须做到“单开关降级”——把全局池切回节点本地前缀共享，命中率下降但索引与搬运开销同时消失，这是在索引吞吐或互联带宽成为约束时唯一能保住TTFT的退路；规模上限正由这两者决定，而非由池容量决定。</p>\n<h3 id=\"alg-kvcache-centric-mooncake-sec-46\">四十六 · 同族算法的分界坐标</h3>\n<p>把 KV 中心分离式池化放回同族算法谱系里，需要先立两根坐标轴，而不是按名字排座次。第一根轴是<strong>复用粒度</strong>：复用发生在 token 块级、请求级还是阶段级。第二根轴是<strong>决策视野</strong>：调度决策只看单卡本地状态，还是看整个集群的全局状态。分页KV批量Rollout落在“块级复用 × 单卡视野”的格子里，它的前缀共享在卡内完成，块表是本地数据结构，调度器不需要知道别的节点持有什么。预填解码分离Rollout落在“阶段级复用 × 集群视野”的格子里，它按 prefill 与 decode 两个阶段拆池，视野是集群的，但复用的对象是阶段资源而不是具体前缀内容。KV 中心池化落在“块级复用 × 集群视野”的格子里，这是三者中唯一同时要求细粒度复用与全局成本比较的位置，也是它复杂度最高的根源。</p>\n<p>这个坐标直接决定了三者的代价结构。单卡块级复用的元数据开销被限制在一张卡的显存里，索引查询是本地访存，延迟可控；阶段级拆池的调度开销在集群层，但每个请求只做一次阶段归属判定，判定频次低。KV 中心池化两者都要：每个请求到达时做一次全局最长前缀匹配，匹配结果还要参与节点选择，索引查询频次与请求到达率同阶。这就是为什么它的失败模式里“索引查询成为瓶颈”排在第一位——不是实现粗糙，而是坐标位置本身带来的固有开销。</p>\n<div class=\"formula\">$$\\text{hit} = \\frac{\\sum_i \\ell_{\\text{prefix},i}}{\\sum_i L_{\\text{prompt},i}},\\quad T_{\\text{prefill}} = \\frac{(L_{\\text{prompt}}-\\ell_{\\text{prefix}})\\cdot C}{\\text{FLOPS}} + \\frac{\\ell_{\\text{prefix}}\\cdot M_{\\text{kv}}}{\\text{BW}_{\\text{link}}}$$</div>\n<p>上式是选型时的第一把尺子。它把 prefill 时间拆成“未命中部分要算”和“命中部分要搬”两段，第二段是否划算完全取决于 $\\text{BW}_{\\text{link}}$ 与 $\\text{FLOPS}$ 的相对量级。在 NVLink 5 域内，搬 KV 的代价远低于重算；一旦跨出 NVLink 域走以太网，第二项就可能压过第一项，命中反而变慢。所以“是否值得全局池化”不是架构偏好问题，而是先算这个不等式：$\\ell_{\\text{prefix}}\\cdot M_{\\text{kv}}/\\text{BW}_{\\text{link}} &lt; (L_{\\text{prompt}}-\\ell_{\\text{prefix}})\\cdot C/\\text{FLOPS}$ 成立的拓扑范围，才是池化该覆盖的范围。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-47\">四十七 · 决策表：按负载形态选族</h3>\n<p>下表把选型条件压缩成可核对的判据。每一行给出一个主导负载特征，对应的推荐算法族，以及不选它的代价。表中不出现具体倍数，因为倍数依赖拓扑与模型，只给定性方向。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>推荐族</th><th>关键判据</th><th>选错的代价</th></tr></thead><tbody>\n<tr><td>单卡内高并发、前缀短且分散</td><td>分页KV批量Rollout</td><td>前缀长度占比低，跨节点搬运不划算</td><td>全局索引开销吃掉本就有限的命中收益</td></tr>\n<tr><td>prefill 与 decode 资源争抢严重、前缀重复一般</td><td>预填解码分离Rollout</td><td>阶段间干扰是主要瓶颈，而非重复计算</td><td>池化引入的元数据与迁移成本无处摊销</td></tr>\n<tr><td>group rollout 同 prompt 多采样、多轮对话历史长</td><td>KV 中心分离式池化</td><td>命中率高且 KV 块集中在 NVLink 域内</td><td>重复 prefill 算力持续浪费，TTFT 随历史长度线性上涨</td></tr>\n<tr><td>前缀重复高但权重版本高频切换</td><td>池化 + 版本分区，或退回阶段拆池</td><td>版本失效周期短于缓存重建周期</td><td>命中率周期性塌陷，池容量被死块占满</td></tr>\n<tr><td>跨地域多集群、互联带宽受限</td><td>域内池化 + 域间只做请求路由</td><td>跨域搬运项压过重算项</td><td>KV 搬运占满互联带宽，decode 粘滞失效</td></tr>\n</tbody></table>\n<p>读这张表的方法是从第三列往回推：先确认瓶颈到底是“重复计算”还是“阶段干扰”还是“互联带宽”。只有确认瓶颈是重复计算、且复用块能在低搬运成本域内取到时，池化才是正解。若瓶颈是阶段干扰，池化不但不解决问题，还会把调度器变成新的争抢点——prefill 节点选择要同时考虑 KV 所在位置与队列负载，这两个目标在高压下互相拉扯。</p>\n<p>一个具体例子：多轮对话场景中，第 $k$ 轮请求的 prompt 包含前 $k-1$ 轮全部历史，$\\ell_{\\text{prefix}}$ 随轮次单调增长而新增 token 很少。此时 $\\text{hit}$ 接近 1，池化的收益几乎等于把整个历史 prefill 全部跳过。反过来，若同一集群里跑的是大量互不相关的短 prompt 单轮请求，$\\text{hit}$ 接近 0，池化的每一次索引查询都是纯开销，此时分页KV批量Rollout 的本地块管理反而是更优解。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-48\">四十八 · 节点选择的收益-成本判据</h3>\n<p>池化的调度核心是一个带传输惩罚的最大化问题，而不是简单的“就近命中”。</p>\n<div class=\"formula\">$$\\max_{n} \\left( C_{\\text{hit}}(n) - \\frac{S_{\\text{KV}}(n)}{BW(n)} \\right)$$</div>\n<p>$C_{\\text{hit}}(n)$ 是节点 $n$ 上可复用前缀节省的 prefill 算力，$S_{\\text{KV}}(n)$ 是需搬运的 KV 字节数。这个式子的工程含义是：命中收益必须扣除搬运时间后才可比。两个节点持有相同前缀时，持有块更多但链路更窄的节点未必胜出；反之，块少但同处一个 NVLink 域的节点可能更优。选型对照时，分页KV批量Rollout 没有这一项，因为它的复用不跨节点，$S_{\\text{KV}}$ 恒为零，决策退化为本地块表查找；预填解码分离Rollout 有搬运项但只发生在阶段边界，频次远低于逐请求匹配。</p>\n<p>伪代码层面的判断顺序应是：先做最长前缀匹配拿到候选块列表，再对每个候选节点算上式，最后叠加队列负载做惩罚。队列负载必须作为独立项而非折进 $BW(n)$，否则高负载节点会因为“看起来带宽高”而被误选。这一步的代价是每次请求多一次全局索引查询加若干次节点评分，索引查询吞吐因此成为规模上限——这正是可用事实里“规模上限受索引查询吞吐与互联带宽约束”的由来。工程上常见的缓解是把索引做成两级：热前缀走内存索引，冷前缀走批量扫描，用热度标记驱动分级，而不是对所有块一视同仁。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-49\">四十九 · 与阶段拆池的组合边界</h3>\n<p>池化与预填解码分离Rollout 不是互斥选项，而是可以叠加的两层。分离式架构提供的是资源隔离：prefill 池与 decode 池各自扩容，互不挤占。池化提供的是跨请求复用：在 prefill 池内部，命中前缀的请求跳过计算。叠加后的结构是“分离式骨架 + 池化填充”，但叠加有边界条件：decode 阶段的粘滞策略要求请求留在持有其 KV 的节点，这与分离式架构“decode 池独立扩容”的弹性直接冲突。当 decode 池需要扩缩容时，粘滞的请求被迫迁移，$S_{\\text{KV}}$ 一次性付清，TTFT 出现抖动——这正是失败模式里“decode 粘滞策略失效导致 TTFT 抖动”的机制来源。</p>\n<p>边界判据可以写成：decode 池的扩缩容周期若短于请求的平均 decode 时长，粘滞收益不足以抵消迁移成本，此时应放弃粘滞、允许 KV 随请求流动，把池化限制在 prefill 侧。反之，decode 时长长、扩容稀疏的场景，粘滞几乎无代价，池化可以贯穿两个阶段。选型时这条判据比“是否分离部署”更细，因为它决定的是池化的作用域而不是部署形态。</p>\n<p>另一个组合边界在权重版本。RL 后训练中权重高频更新，池中块按版本失效。若把池化叠在分离式架构上，失效会同时打击 prefill 池的命中率与 decode 池的粘滞有效性：前者表现为 $\\text{hit}$ 周期性归零，后者表现为持有旧版本 KV 的节点不再能服务新请求。缓解手段是按版本分区而不是全池失效——新版本请求只匹配新版本块，旧块在 LRU 下自然淘汰，避免一次性清空导致的容量空窗。代价是池的有效容量被版本数整除，版本切换越频繁，可用于复用的容量越小，这是选型时必须计入的隐性成本。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-50\">五十 · 适用条件的量化门槛</h3>\n<p>把适用条件写成可测门槛，比写成“适合高重复场景”有用。第一道门槛是命中率：$\\text{hit}$ 必须高到使节省的 prefill 算力超过索引与迁移开销。由于开销与请求到达率同阶、收益与 $\\ell_{\\text{prefix}}$ 同阶，门槛实际是“平均可复用前缀长度 × 到达率”要显著大于“索引查询成本 × 到达率”，即平均前缀长度本身要够长。短前缀高并发是池化最不利的组合：查询频次拉满，单次收益很小。</p>\n<p>第二道门槛是拓扑：可复用块必须落在搬运成本低于重算成本的域内。NVLink 5 域内满足，跨域不满足时池化应收缩到域内，域间只做请求路由不做 KV 搬运。第三道门槛是版本稳定性：权重更新间隔要长于缓存重建所需的时间，否则命中率在“刚重建完又失效”的循环里震荡，池化的调度开销持续付出而收益间歇归零。三道门槛任一不满足，就应退回分页KV批量Rollout（本地块管理）或预填解码分离Rollout（阶段隔离），把复杂度花在真正的瓶颈上。</p>\n<p>最后一道工程判断落在索引的可扩展性上。池化的规模上限不由 GPU 数量决定，而由前缀索引的查询吞吐决定：每来一个请求就要做一次最长前缀匹配，匹配的数据结构若是集中式，其吞吐就是整个集群的吞吐天花板。选型时应先估这个吞吐是否跟得上目标 QPS，跟不上就不要上全局池化，改用按节点分片的局部索引加请求亲和路由——牺牲一部分全局命中率，换取索引不成为单点。这个取舍本身就是同族算法选择的实质：不是选最强的机制，而是选开销结构与负载形态匹配的那一个。</p>\n\n<h3 id=\"alg-kvcache-centric-mooncake-sec-51\">五十一 · 选型边界：何时该用全局KV池，何时退回同族方案</h3>\n<p>同族三条路线并非替代关系，而是按“复用半径”分层：分页KV批量Rollout把块级分配与前缀共享锁在单卡内，预填解码分离Rollout按阶段拆池、各管一段，本方案则把KV cache升为一级调度对象跨节点比较成本。判据是复用跨度是否越出单节点显存与单阶段边界。若group rollout的多条采样与多轮历史引用落在同一节点、同一阶段内，单卡分页共享已能吃掉重复前缀，引入全局索引只增加元数据路径；只有当同一前缀被不同节点、不同批次的请求反复引用，跨节点复用收益才压得住索引与搬运开销。选型时先量命中率<span class=\"formula\">$$\\text{hit} = \\frac{\\sum_i \\ell_{\\text{prefix},i}}{\\sum_i L_{\\text{prompt},i}}$$</span>再量搬运占比，hit高而<span class=\"formula\">$$S_{\\text{KV}}(n)/BW(n)$$</span>低才成立。</p>\n<p>决策表按三个维度切分：前缀重复来源、权重更新频率、互联带宽余量。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>首选方案</th><th>失效信号</th></tr></thead><tbody><tr><td>重复前缀限于单节点、单阶段</td><td>分页KV批量Rollout</td><td>跨节点重复率高但池未建，prefill重复计算</td></tr><tr><td>prefill与decode负载形态差异大、复用少</td><td>预填解码分离Rollout</td><td>阶段拆池后命中率仍低，拆池收益被搬运抵消</td></tr><tr><td>前缀跨节点反复引用、权重版本稳定</td><td>全局KV池（本方案）</td><td>索引查询吞吐打满、搬运占满互联带宽</td></tr><tr><td>RL高频权重更新</td><td>退回阶段内共享，池只做版本内复用</td><td>版本切换致缓存大面积失效，命中率周期性塌陷</td></tr></tbody></table>\n<p>本方案的硬边界由两笔代价划定。其一是索引开销：全局前缀索引在高并发下查询本身成为瓶颈，命中率收益被元数据开销抵消，此时应收缩池的注册粒度或退回节点内共享。其二是版本失效：RL后训练权重高频切换使相关KV块按版本失效，缓存大面积作废，命中率周期性塌陷，prefill算力节省归零——在这种负载下把池容量做大的边际收益为负，正确做法是把池限制在单版本生命周期内，用LRU+热度淘汰控制容量，而非追求跨版本长驻。传输侧同样有边界：跨节点KV搬运占满互联带宽时，decode粘滞策略失效，TTFT出现抖动，此时应优先保证粘滞而非追求更高命中率。</p>\n<p>工程判断落在调度目标函数上：<span class=\"formula\">$$\\max_{n} \\left( C_{\\text{hit}}(n) - \\frac{S_{\\text{KV}}(n)}{BW(n)} \\right)$$</span>其中<span class=\"formula\">$$C_{\\text{hit}}(n)$$</span>是节点n可复用前缀节省的prefill算力，第二项是搬运代价。该式说明选型不是“命中率越高越好”，而是命中收益必须超过搬运与索引的合成成本；当互联带宽被其他流量挤压、或索引查询延迟进入TTFT关键路径时，最优解自动退化到节点局部共享，这也是同族方案在本方案失效条件下仍应保留为兜底路径的原因。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2024 · NVFP4采样与量化稳定性</td></tr><tr><td>解决什么</td><td>RL后训练中同一prompt被多次采样、多轮对话反复引用历史，KV重复计算严重；分离式架构下KV调度缺乏全局视角，缓存…</td></tr><tr><td>一句话机制</td><td>以KV cache为一级调度对象，建立全局可复用前缀池，prefill调度优先命中缓存块，未命中才计算，并按传输成本选…</td></tr><tr><td>代价与失效</td><td>全局前缀索引与块迁移带来元数据开销，高并发下索引查询可能成为瓶颈；权重版本切换使缓存大面积失效，RL高频更新场景下命中率周期性塌陷</td></tr><tr><td>后继</td><td>异步rollout权重同步</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-kvcache-centric-mooncake · 共 8 个片段</p>\n";break;}}})();
